quests[26969] = { id = 26969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Strike", description = "Your walk with the elemental powers will take you to many places. As you grow in power, you will begin to learn new abilities. \n\nLet us start your journey with a simple, but useful, lesson.\n\nLearn the secret of Primal Strike, and then practice your new skill using the training dummies to the northwest of the Crash Site. Return to me when you are finished.", completion = "It is a pleasure to teach such a capable student. As long as you continue the traditons faithfully, the shamanic arts will never be lost to our people again. Return to me when you need further training.", objectives = "Learn Primal Strike by reaching Level 3, and then find a Training Dummy on the northwest side of the Crash Site and practice using Primal Strike 3 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26970] = { id = 26970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Word", description = "As a priest, one of your most important duties is to use the Light's power to aid the wounded.\n\nAnother is to use your power offensively, to protect them.\n\nAs you grow more experienced, you will begin to uncover new abilities that you can use in your charge. Go, gain more experience, and then demonstrate the abilities you have learned to me.", completion = "You'll often find your skills as a healer in demand, {name}. Do not hesitate to return when you need more training.", objectives = "Reach level 3 to learn Shadow Word: Pain, then use it 5 times on target dummies near the crash site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26971] = { id = 26971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "A noise in the main chamber of the temple draws your attention. You hear a familiar laugh... Lorthuna. She's returned to interrupt the ritual - you must stop her!", completion = "Maruut said when all dis started dat he would gladly give his life ta see our task done. He would be proud of dis success... of dis death.\n\nDa rift be closed on dis side. Deepholm should calm down a bit. It'll be takin' time for Thrall to mend da wound in Azeroth, and we'll be needin' to remain until he finishes.\n\nThank you for all ya've done. I don't tink we could have been accomplishin' dis so soon without you.", objectives = "Kill High Priestess Lorthuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26972] = { id = 26972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Side of the Light", description = "I joined the Scarlet Crusade as a young paladin, eager to cleanse the world of evil. Little did I know of the dark truth to these fanatics.\n\nInterrogator Vishas and Bloodmage Thalnos oversee this graveyard. They take great pleasure in torturing new recruits endlessly to ensure that they are 'pure'. It is an affront to the light, {class}!\n\nNo longer can I be a part of this corrupt organization. You're going to have to kill them both, so that others will never endure the same pain I did.", completion = "What do you mean Thalnos was an undead? That's impossible. The entire mission of the Scarlet Crusade is to destroy the undead! There's just no way...\n\nYou have muddied my thoughts. Please take this reward for your achievement and leave me to rest.", objectives = "Kill Interrogator Vishas and Bloodmage Thalnos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26973] = { id = 26973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only True Path", description = "I think that the root of the crusade's corruption can be found here. Arcanist Doan watches over the library, and teaches many young recruits to wield the arcane arts.\n\nThe Light is the only true path! You must kill him, {class}, and redeem this glorious movement!\n\n<Joseph the Awakened shifts nervously.>\n\nYou'll want to dispose of Loksey as well. His hounds seem to disapprove of our noble intent.", completion = "Good work! I just know the Light shines favorably upon us for our work. Our cause is righteous!", objectives = "Eliminate Houndmaster Loksey and Arcanist Doan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26974] = { id = 26974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The False Champion", description = "We...we...we had to kill them! They were coming right for us!\n\nYou believe me, don't you {name}?\n\nHerod is not the true champion of the Scarlet Crusade. I am! He took what was rightfully mine!\n\nYou should kill him. He's...a menace! Trains the soldiers to kill anyone instead of just the undead!\n\nI'll reward you handsomely...", completion = "So he's really dead? That means...I, Joseph, am the new Scarlet Champion!!!\n\nTake this. I don't have a need for such possessions anyways! I'm the Scarlet Champion, after all.", objectives = "Kill Herod.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26975] = { id = 26975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rallying the Fleet", description = "I am amassing a warfleet to assault Twilight Highlands and bring an end to Deathwing's lackeys. My soldiers are ready but fleet preparations lag behind.\n\nMy men at the docks need some inspiration and motivation. A visit from the Prince here should lift their spirits and remind them of the bright future they're fighting for.\n\nTake Prince Anduin to the docks with you and speak with Supply Sergeant Graves. I want Anduin to observe how a natural leader handles the situation.", completion = "<Graves bows respectfully to the Prince.>\n\nPlease understand your highness, the men are working double-shifts. The scale of your father's operation is enormous.\n\nBut we will endeavor to wrap things up. I give you my word.", objectives = "Escort Prince Anduin to the Stormwind Docks and talk to Supply Sergeant Graves. If you get separated from the Prince, you'll find him in the Stormwind throne room.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26976] = { id = 26976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for the Scarlet Monastery", description = "Oh, it's great to see you again {name}! I'm afraid I'm going to need your help.\n\nYou see, Mograine's the Commander here along with High Inquisitor Whitemane, and they tried telling me that I wasn't really the new Scarlet Champion! 'Course, the boys and I didn't take kindly to that.\n\nWe're taking the Scarlet Monastery for our own and re-establishing the order as it always should have been - with me at the head of things! I'll take care of the Forsaken and the Scourge for good.\n\nHelp an old friend out?", completion = "Yes! The Scarlet Monastery is ours! You're a real friend. Take this as a reward, and feel free to visit again once I've taken the Undercity too.\n\nIt'll be a Scarlet Paradise!", objectives = "Kill Scarlet Commander Mograine and High Inquisitor Whitemane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26977] = { id = 26977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Investigation", description = "The city is still reeling from the seditious acts of the Twilight's Hammer in recent months. They prey on peasant fears and corrupt our most important citizens. We need to find out how deep the conspiracy runs.\n\nI've tasked Major Samuelson of the Stormwind City Guard to head up an investigation. He's right here in the throne room. See if you can assist his efforts.", completion = "Hmmm, yes? My investigation of the Twilight's Hammer. Of course.\n\nYour assistance will be valuable.", objectives = "Speak with Major Samuelson in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26978] = { id = 26978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Needs Cauldrons?", description = "Have you seen the condition of Felstone Field?  The Alliance forces at Andorhal have taken the area, and they're using it to... to... to grow CROPS!\n\nI almost liked it better when the Scourge held the area.  At least they had the sense to put a giant plague cauldron in the middle of the field.\n\nWe're going to take that farm back from these humans, {name}.  Take these drums and place them at key locations around the field.  I'll be waiting here at the Bulwark.", completion = "<Dithers practically glimmers with excitement.>\n\nThe drums are placed?  In their positions?\n\nVery well then, I will give the word to the High Executor.  When the time is ready, he will be the one to press the ignition switch.", objectives = "Place Dithers' Plague Drums near the Windmill, the Grain Silos, the Ranch House, and the Barn at Felstone Field.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26979] = { id = 26979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange New Faces", description = "Now that Felstone is ours, we can use its acreage - and any dead bodies we find - for our own purposes.  I've received orders from higher up that you are going to be helping out in this process.\n\nYou may have met Lindsay Ravensun on the battlefield in Andorhal.  I've never met her before, but she seems to have made some friends in high places, because she's taking over operations at Felstone.  You're to meet her at the charred Scarlet camp... the one you scouted out earlier.", completion = "{name}.  The Dark Lady watches over you.", objectives = "Report to Lindsay Ravensun at the Charred Outpost in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26980] = { id = 26980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swiftgear Station", description = "You've done good work here, {name}. Askin' you to haul sandbags would be a waste, to be honest; I'd rather send you along where your skills are needed.\n\nWe've got a small outpost up north in the marsh. Swiftgear's the gnome that built it, but you'll want to talk to Shilah Slabchisel and help her with Ironforge matters.\n\nI'll admit, she's a looker... but I wouldn't make the mistake of getting fresh with her! They don't call their family Slabchisel for nothing.", completion = "Stoutfist sent you, eh? He's a good captain, runs his men well. Just wish he'd stop starin' at my midriff.\n\nDon't let me catch you doin' it either. We've work to take care of here!", objectives = "Speak with Shilah Slabchisel at Swiftgear Station, north of Menethil Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26981] = { id = 26981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whelgar's Retreat", description = "Prospector Whelgar's been leading an excavation in the mountains southeast of here for quite some time. He had some raptor problems back in the day, but things were going better recently.\n\nJust the other day, we got word he had to evacuate the entire digsite again. I'm not sure what's going on there, but I can't imagine the cataclysm making a quarry any safer than it was before.\n\nThere's good dwarves working there, {name}. Would you go see what's wrong there, and maybe lend a hand?", completion = "Well met, {class}. We've got raptor problems for sure... sort of.\n\nMore like the entire dig site deciding to attack us. I've never seen rocks and fossils get so upset!", objectives = "Speak with Prospector Whelgar at Whelgar's Retreat, southeast of Swiftgear Station.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26982] = { id = 26982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Monastery", description = "The same Monastery in Tirisfal Glades that the Scarlet Crusaders now occupy used to be a major training ground for our paladins. Now the Forsaken loom over it from the Undercity and the Crusade prevents us from utilizing it to train the very soldiers we need to deal with the Forsaken!\n\nLook, I don't trust him, but Joseph the Awakened waits inside the graveyard. Go speak with him - although he is a crusader, he says he now rebels against them, providing us with an opportunity to take back what's ours.", completion = "Captain Nials sent you? I haven't seen her in ages! How is she? Did she get my letter?\n\nOh, you're not here for that. Well then, let's get down to business!", objectives = "Visit Joseph the Awakened.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26983] = { id = 26983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Close Enough", description = "Make no mistake - there is a ton of stuff to be done here! However, we also need to strike at the Forsaken where it hurts. The Scarlet Monastery in Tirisfal Glades is the perfect distance from the Undercity and Brill.\n\nReport to Joseph the Awakened in their Library. He's a rebel crusader that can hopefully help us take the Monastery as our base of operations in that region, and maybe take out Arcanist Doan, one of their most powerful mages, in the process.", completion = "You came here from Southshore, eh? I bet you hunger for revenge against the vile Forsaken that trashed the place. The Scarlet Crusade can help take care of that!\n\nRight after you help me realign their misguided souls, that is.", objectives = "Visit Joseph the Awakened.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26984] = { id = 26984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old, Crazed Friend", description = "Joseph the Crazed was one of my good friends before he joined the Scarlet Crusade up in the Scarlet Monastery in Tirisfal Glades. I heard that he's in the Armory there trying some ridiculous attempt at taking over Herod's position as Scarlet Champion.\n\nIt's a death wish to challenge Herod like that! Go up there and try to talk him out of it.", completion = "You look pretty tough, {class}. There are wrongs to be righted here. Let's get started.", objectives = "Visit Joseph the Crazed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26985] = { id = 26985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pitting Madness Against Madness", description = "Our renewed forces can handle the situation here for a while without you. I've received reports that Joseph the Insane, a former Scarlet Crusade officer, is in the Scarlet Monastery Cathedral and is taking his band of renegades to strike out against Scarlet Commander Mograine.\n\nThis is an excellent opportunity. Go there and help him with his insane task, and maybe we can use the Monastery as an excellent stronghold right at Sylvanas' doorstep!", completion = "Wait, you were sent here by THE Shandris Feathermoon? I can barely believe my ears! To know that my cause is supported by her massive army...\n\nYes, yes, you will be perfect. You're the key to my future!", objectives = "Visit Joseph the Insane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26986] = { id = 26986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Scarlet Monastery", description = "Oftentimes the best way to ensure our men sustain as few injuries as possible is to cause great harm to our enemies in their very homes and prevent battles from ever occurring!\n\nTravel to the Scarlet Monastery and speak with Dark Ranger Velonara in their graveyard. She is leading a Forsaken assault there and could benefit from a seasoned {class} such as yourself.", completion = "It looks like Darthalia sent an able {class}, as I requested.", objectives = "Report to Dark Ranger Velonara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26987] = { id = 26987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Way", description = "My people are not generally fond of the arcane arts that so many other races abuse. Thankfully the wizards within the Scarlet Monastery library are separated from us by considerable land, but their ability to transcend the physical realm concerns me and, ultimately, my tribe's survival.\n\nTravel far to the west to the monastery's library and speak with Dark Ranger Velonara there. Her forces are already poised to strike at Arcanist Doan himself, head magi for the crusade.", completion = "I'm surprised to see Huntsman Markhor working with me for once. He's usually quite stubborn. He does tend to a strong hatred for magic, though.\n\nI hope you do, too, {class}, because we're going to strip the Scarlet Crusade of theirs.", objectives = "Speak to Dark Ranger Velonara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26988] = { id = 26988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moving Things Along", description = "I'm waitin' on some very powerful reagents I ordered from the Undercity not long ago. I heard that the shipment is late because the Scarlet Monastery's crusaders are blocking its passage. Da Scarlet Champion, Herod, is likely to blame for dis annoyance.\n\nPlease go speak to Dark Ranger Velonara in the Scarlet Monastery's armory, she is goin' to 'take care' of Herod, which means my shipment will arrive safely!", completion = "Yayo'jin is correct, you helping me here will aid her in the Hinterlands as well.\n\nAll the more reason to get started immediately.", objectives = "Visit Dark Ranger Velonara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26989] = { id = 26989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gilneas Liberation Front", description = "The battle over this region still rages, {name}nub. Although we soundly beat back the Gilnean defenses and took Gilneas for the Horde, a small group of rebels managed to escape. The \"Gilneas Liberation Front\" - as they call themselves - make attacks of opportunity against our forces in the field. The rebels have had a few minor victories and now grow brazen in their assaults! The time to strike back is now, {name}nub.\n\nVenture south into the wilds of Silverpine and kill any rebel that you cross.", progress = "What have you to report, Duridnub?", completion = "Vorelocknub has returned! And in one piece!\n\nDefender of Silverpine! Redeemer of the Horde! Vorelocknub, your bravery must be rewarded!", objectives = "Kill 10 Worgen Renegades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26990] = { id = 26990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water They Up To?", description = "It appears that the Sandfury trolls are working with the Twilight's Hammer.\n\nNo matter. That foul witch won't be sending her monster to MY city.\n\nCome, brave ones! We'll slick the sand with their gore and return home triumphant. Tell Hamuul Runetotem what's happened here when we've gotten back; I'll need to oversee the return of the citizenry, repairs, and so on.", completion = "Sandfury trolls and the Cult of Twilight's Hammer, you say?\n\nAnd they meant to send some giant monster into the heart of the city?!\n\nWell done! Thunder Bluff is in your debt.", objectives = "Slay Kai'ju Gahz'rilla and inform Hamuul Runetotem in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26991] = { id = 26991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Abroad", description = "Sometimes we must acknowledge the need to protect our allies so that they may protect us. This is one such occasion, {race}.\n\nTravel to the Scarlet Monastery near the Undercity in Tirisfal Glades. Once you arrive, go to the Cathedral and speak with Dark Ranger Velonara. She is leading the final assault against the crusade there, and it would benefit us all greatly to ensure our undead allies secure the monastery before the crusaders have a chance to attack their capital.", completion = "Nazeer is a strong warrior - his hatred for our enemies rivals my own. You are welcome help to my forces.", objectives = "Find Dark Ranger Velonara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26992] = { id = 26992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agony Abounds", description = "You have no doubt heard about the incident that transpired at the Wrath Gate in Northrend, yes? Due to those unfortunate events we are strictly forbidden from using the strain of life-shattering blight that we finally perfected. Now we have rules and regulations and other nonsense!\n\nThey've given us some neutered version of the perfected blight and expect us to weaponize it.\n\nIf I'm to get this crap functional I'll need several bags full of ferocious doomweed. You'll find it all over Silverpine.", progress = "Have you collected the ferocious doomweed I requested?", completion = "Agony abounds, friend! The land itself threatens to devour us, and yet we persist. I wonder why that is? With this doomweed and the guts and gore that T'Veen needs, we might have something suitable to send to the Forsaken front.", objectives = "Gather 8 Ferocious Doomweed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26993] = { id = 26993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Compendium of the Fallen", description = "Don't fret, I serve no master, {race}. Within these halls lies a book called the Compendium of the Fallen. It holds vast amounts of research that the Scarlet Crusade has done on my kind over the years.\n\nSimply put, I'd like you to retrieve it and bring it back to me. No questions asked.", progress = "I don't want to stay in a monastery packed full of undead-hating zealots for much longer. Surely you can understand why. Don't speak to me if you don't have the book with you.", completion = "Well done. How about I give you a nice reward for your work, and you don't tell a soul that you saw me here. Deal?", objectives = "Retrieve the Compendium of the Fallen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26994] = { id = 26994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Without Rhyme or Reason", description = "I heard that Joseph the Crazed wants you to kill Herod. While you're at it, how about you slaughter their top soldiers? I'll pay you well for your work.\n\nDon't worry about the why, just worry about the how.", completion = "Very good. Yes, very good indeed.\n\nYour reward, as promised. No questions.", objectives = "Kill 3 Scarlet Myrmidons, 3 Scarlet Protectors, 3 Scarlet Guardsmen, and 3 Scarlet Evokers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26995] = { id = 26995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guts and Gore", description = "If we're to get this new blight up and running we'll need clean beast guts. The problem is that clean beast guts are a rare commodity in Silverpine Forest. Most of the beasts here have succumbed to disease and thus only have diseased organs.\n\nDo a sweep of the forested area east of here for worgs and grizzled bears. Kill only the non-diseased variety and rip out their entrails. Bring me all of the clean guts that you can stuff into your backpack!", progress = "Remember, I can only use clean beast guts for the new strain of blight we're developing.", completion = "Excellent! With these guts and the ferocious doomweed we'll be able to test out our new strain of blight. Now to select a suitable target...", objectives = "Recover 6 \"Clean\" Beast Guts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26996] = { id = 26996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Right Under Their Noses", description = "In the right side-room of the accursed cathedral ahead there is a torch on the wall. Move it and a secret door will open. Inside is High Inquisitor Fairbanks. He is now an undead.\n\nI need him taken care of. Kill him in his own room if possible, I'd strongly prefer the crusaders not see him. You know the deal - kill him, and I'll reward you. No other words are necessary between us.", completion = "<Dominic hands you your reward. No words are spoken.>", objectives = "Kill High Inquisitor Fairbanks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26997] = { id = 26997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Usual Suspects", description = "<Samuelson scratches his chin, absently.>\n\nMy investigations reveal, ah, it's likely that there's trouble brewing among the Stormwind dock workers. Shifty lot. Don't trust 'em.\n\nYou should go there and shake the place down. Start grilling those longshoremen. That should keep you busy.\n\nGo rout out those Twilight infidels!", completion = "This doesn't make any sense, {name}.\n\nWhy was Samuelson sending us out here on a wild goose chase?\n\nSomething doesn't feel right. We should poke around on our own...", objectives = "Grill 6 Stormwind Dock Workers in Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26998] = { id = 26998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iterating Upon Success", description = "The concoction is finally ready, but before I can put my seal of approval on this strain, we'll need to run a field test.\n\nSpeak to Bat Handler Maggotbreath, here at High Command, and requisition a bat. The bat will take you to the Dawning Isles, east of here across Lordamere Lake, right into the heart of depravity itself - the Vile Fin murloc dens!\n\nUse the concoction against the murlocs and report the results back to me.\n\nThose results being that you killed them all, as commanded!", progress = "Have you exterminated the Vile Fin murlocs of the Dawning Isles?", completion = "Potent enough to exterminate a thousand murlocs! I think I'll put that on the label. You've done well, {name}, and great work around here gets rewarded.", objectives = "Kill 50 Vile Fin Murlocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26999] = { id = 26999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Era for the Plaguelands", description = "No longer does the Scourge hold this area.  We, the living, are retaking Lordaeron.\n\nWe have taken great strides already, as you have already seen.  The earth flowers, the trees grow tall and green, and the wildlife is beginning to return.  Yet a few remnants of undeath remain.\n\nWhile the trees and grass prosper, the animals are struggling.  Something is preventing them from healing, and I intend to find out what.  Bring me samples from the plagued wildlife so that I may study them more closely.", progress = "Once the animals are healed, our duties here will be nearly complete.", completion = "This will be more than enough, {name}.  Now, I will need some time to perform my studies.", objectives = "Obtain 4 Plague Lurker Samples, 4 Venom Mist Lurker Samples, 4 Hulking Plaguebear Samples, and 4 Diseased Wolf Samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27000] = { id = 27000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Ropes", description = "Ah, it's good to be back in Northridge!  I've got my mill, my beautiful wife, a bouncing baby boy... I've even put in my hat with the Argent Crusade.  We'll be supplying Tirion's forces with lumber.\n\nMy lumberjacks were being exceptionally productive, too... up until the point when the spiders came.  Now they refuse to go any deeper in the woods.\n\nMaybe you can help me out.  Hop on one of my horses and use it to frighten those spiders.  Maybe we can avoid bloodshed and just scare them away.", progress = "The spiders tend to be a little skittish.  One of the mustangs should be enough to scare them away.", completion = "Well, it sounds like they're certainly afraid of the mustang, but they're not leaving for good.  I can't have you running around on a horse forever.  Nor do I think you'd want to.\n\nFine.  Bloodshed it is.", objectives = "Mount a Hearthglen Mustang at Northridge Lumber Mill, then use its Whinny ability to frighten 25 Northridge Spiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27001] = { id = 27001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Means WAR (Wild Arachnid Roundup)", description = "The Highlord was generous enough to send some of his recruits to protect us here at the mill.  With your horsemanship skills, and their martial prowess, we can do away with this spider problem easily.\n\nHop back on that mustang and scare those spiders again, but this time, scare them all the way up here to the mill.  These Hearthglen recruits can handle things from there.", completion = "That's much more like it!  Now my lumberjacks can get to work again.\n\nNice riding out there, {name}.  You cut a pretty impressive silhouette on that mustang.", objectives = "Mount a Hearthglen Mustang near the Northridge Lumber Mill, then use its Whinny ability to send 10 Northridge Spiders to the Hearthglen Recruits at the Northridge Lumber Mill. You can round up several spiders at once.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27002] = { id = 27002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience with the Highlord", description = "Oh, before you go, {name}... I have a message for you.  There's someone in Hearthglen who'd like to meet with you.  Said he's \"heard your name pop up\" a few times already.\n\nConsider yourself lucky, {name}.  Not everybody gets a personal audience with Highlord Tirion Fordring.\n\nOh, and feel free to use one of my mustangs for the ride up there.  They're the fastest money can buy.", completion = "{name}.  It is truly a pleasure.\n\nI know you are young, and still training, but I've had my eye on you.  We among the Argent Crusade are always looking for promising new recruits, and you have indeed shown great promise.  I have no immediate tasks for you, but merely wished to meet you in person, and see for myself what type of {race} you really were.\n\nFor the time being, the amenities of Hearthglen are yours to enjoy.  I look forward to our next meeting, {name}.  You are dismissed.", objectives = "Report to Highlord Tirion Fordring at Hearthglen in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27003] = { id = 27003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy Money", description = "Well, hello there!\n\nWhatever brought you, I'm so glad that you're here! My friends will never admit to it, but we could really use a hand.\n\nThe ancient region of Uldum has been exposed! Treasures beyond your wildest dreams, free for the taking!\n\nWe just need a bit of an escort, what with the bandits and all...\n\nYou'll accompany us, won't you?\n\nYou're welcome to all the loot you can haul off!", completion = "Smells like someone else was in this cell recently.\n\nGross!", objectives = "Accompany Adarrah's caravan into Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27004] = { id = 27004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Plot", description = "We came here to investigate rumors of a Titan artifact up at the Masters' Gate to the southwest.\n\nOne of those Twilight's Hammer cultists must have the plans for what they're doing up there. You're going to have to get them for us, {name}.\n\nKeep searching the cultists until you find them.", progress = "Those plans are the key to everything.", completion = "<Mowi takes a look at the plans that you hand to her.>\n\nBut... but, this is just gibberish!\n\nWhat does this even say? What language is that?", objectives = "Collect the Masters' Gate Plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27005] = { id = 27005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Plot", description = "We came here to investigate rumors of a Titan artifact up at the Masters' Gate to the southwest.\n\nOne of those Twilight's Hammer cultists must have the plans for what they're doing up there. You're going to have to get them for us, {name}.\n\nKill cultists at the Masters' Gate until you find them.", progress = "Those plans are the key to everything.", completion = "<The examiner takes a look at the plans that you hand to him.>\n\nThis is just gibberish!\n\nWhat does this even say? What language is that?", objectives = "Collect the Masters' Gate Plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27006] = { id = 27006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fly Over", description = "I tried ta fly o'er the terrace an have a look fer myself, but those toastie eatin' pansies kept shootin' at me, an I couldn't get near.\n\nYa look like ya might be handy with the reins. Why don' ya take yer flyin' beastie up there ta the southwest and see what all the fuss is about?", progress = "What'd ya see? What are those cheese lovers up ta?", completion = "A waygate?! The culties dug up a Titan waygate?", objectives = "Investigate the central area in the back of the Masters' Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27007] = { id = 27007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silvermarsh Rendezvous", description = "Excellent work, {name}.  We know exactly where the meeting location is.\n\nThe Upper Silvermarsh is a mercury swamp to the east of here.  It's normally only inhabited by elementals and occasional stone troggs, but our scouts have seen some Twilight activity in the region.\n\nMake your way there and let's find a way to eavesdrop on the Forgemaster's meeting.", completion = "This is the place.  Our scouts confirmed the presence of high-ranking Twilight officers nearby as well as potential trogg hunting parties.\n\nBe on the lookout, {name}.", objectives = "Go to the Upper Silvermarsh in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27008] = { id = 27008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fly Over", description = "I'm quite adept at riding my flying carpet. Unfortunately, when I tried to investigate what the cultists had uncovered up at the Masters' Gate, they nearly shot me down.\n\nYou look as if you might be skilled with the flying reins as well. Would you mind flying up there to the southwest to see what they've unearthed?", completion = "A waygate?! They unearthed a Titan waygate.\n\nThis is very interesting and potentially very bad.", objectives = "Investigate the central area in the back of the Masters' Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27009] = { id = 27009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Coldbringer", description = "Amnennar the Coldbringer rules over the Razorfen Downs with very dark and powerful Scourge magic. I have managed to clear an opening in the thorns just above his seat of power, but his sorcery prevents me from launching an assault.\n\nIf you venture up the Spiral of Thorns and engage him, he will be distracted long enough for me to attack him briefly, weakening him before he can use his most deadly spells. Once he is weakened, destroy him without mercy.", completion = "A job well done, {name}. The Quilboar here can no longer be saved, but at least they are no longer organized for attack, or slaves under Amnennar's tyrannic rule.\n\nLeave quickly, please. Razorfen Downs is without hope. It must be purged.", objectives = "Kill Amnennar the Coldbringer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27010] = { id = 27010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quicksilver Submersion", description = "The troggs in Deepholm have proven to be every bit as hostile as the ones in Azeroth.  Yet perhaps their presence will prove useful to our efforts.\n\nThe crates they use for trawling through the mercury will conceal you perfectly if you submerge yourself beneath the marsh.\n\nUse it to approach the Twilight's Hammer camp in the eastern end of the Upper Silvermarsh undetected.", completion = "We have the information we need.  Let's not tip our hand by engaging the enemy too soon.", objectives = "Obtain a Trogg Crate and use it to submerge yourself and eavesdrop on the Twilight's Hammer camp to the east.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27011] = { id = 27011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redpine Thievery", description = "Farther to the south, you will find Redpine gnolls... a new arrival to the area.  You probably passed some on your way here.  Nathaniel pretends like they're not a problem, but I know better.\n\nI've seen them running away with our lumber at night.  I don't know what they'd do with lumber - they don't seem particularly handy - but that doesn't stop them from stealing it.  Head down to their camps and steal that lumber back.", progress = "Some of the older lumberjacks tell me that the Redpine lived in the area several years ago, but left when the plague arrived.  That doesn't make it OK for them to steal, though.", completion = "I'll just put this back over in the lumber stores outside.  Nathaniel probably won't even notice it was missing.", objectives = "Retrieve 10 piles of Northridge Lumber from the Redpine Camp in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27012] = { id = 27012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gnoll's Resolve", description = "I have my doubts about those gnolls' intentions.  They haven't attacked us yet, but their numbers are growing, and they seem to always have their weapons ready.  I'm no military expert, but that seems a little aggressive to me.\n\nMaybe if we took away some of their weapons, they'd be a little less likely to pose a threat to our mill.  I'd feel much better about the whole situation if you went down there and brought some of their weapons back to me.", progress = "I don't want to order some sort of mass gnoll genocide because of a mother's worries.  I'd just like to feel safe in my own home.", completion = "Thank you, {name}.  I'll be throwing these in the fire.  We don't want those gnolls just sneaking in and stealing them back.", objectives = "Obtain 6 Redpine Staves and 6 Redpine Clubs from Redpine Gnolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27013] = { id = 27013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Close for Comfort", description = "I'm happy for Nathaniel: he's spent so long trying to return to Northridge, and now with the Scarlet Crusade out of the way, he can finally move back home.  It's just... even for such a seemingly-idyllic setting, it's not really the best place to raise a family.\n\nFor example: along this valley's edge, you will find rabid foxes searching for innocent prey.  Every once in a while I catch a glimpse of one looking right at me.\n\nPlease, {class}, remove some of these foxes.  I don't feel safe with them near.", progress = "I have a family to raise, and I need to do whatever I can to protect them.", completion = "I feel a bit more relieved, {name}.  Thank you.", objectives = "Kill 12 Rabid Foxes near Northridge Lumber Mill in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27014] = { id = 27014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowed Note", description = "Just a moment ago a messenger was looking for you, {name}. I believe she was sent by the priest trainer, Seer Ravenfeather. If this note is from the seer, I would go looking for her immediately.", progress = "I am pleased to meet you, {name}.", completion = "You have arrived at last. During your training in Camp Narache, I will guide you in the ways of the {class}. You have much to learn and I look forward to counting you among my students.", objectives = "Speak to Seer Ravenfeather in Camp Narache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27015] = { id = 27015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consecrated Note", description = "Just a moment ago a messenger was looking for you, {name}. I believe she was sent by the paladin trainer, Sunwalker Helaku. If this note is from the sunwalker, I recommend going to see him immediately.", progress = "I am pleased to meet you, {name}.", completion = "We have much to cover. In time, the ways of the sunwalkers will be as plain and natural to you as the shaman's conversations with the elements.", objectives = "Speak to Sunwalker Helaku in Camp Narache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27016] = { id = 27016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Joy of Boar Hunting", description = "Try to contain your excitement, {name}, for you are in the presence of the greatest boar hunter in Azeroth!\n\nTheir cunning intellect, rapid speed, ferocious strength, and resilient hide... yes, boars are the quarry of only the most masterful of hunters. Amateurs need not apply!\n\nWhy, I bet you've never even hunted such an exotic beast. I'll bet silver any day that you can't match my record of ten boars killed. Try the ones on the eastern shore of the loch... but don't hurt yourself now, rookie!", completion = "You've killed ten already? H...hah! While you were out, I've broken my previous record! To ten... hundred! Yes, ten hundred boars!\n\nA bet is a bet, I suppose... here's your consolation prize, {name}!", objectives = "Kill 10 Mudbelly Boars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27017] = { id = 27017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories from a Lost Past", description = "It's funny the things you remember.  I spent 16 hours a day working the fields, and every seventh day I'd head into bustling Andorhal to sell what I'd grown.  It was a tough life, but we did alright.\n\nBut I barely remember any of that.  When I think back to those days, I think about Gloria's smile, or Andrea waving from the window whenever I'd look up from the plow.\n\nThe farm's just a bit to the east, but I'm not sure I'm ready to go back, {name}.  I'd just like to make sure I hold on to these memories.", progress = "I wouldn't expect you to indulge the whims of a nostalgic old man, {name}.  Still, if you find yourself in the area...", completion = "This... Gloria used to read from this prayer book every night!  How had I forgotten?  She was so devout, {name}.\n\n\n\nOh...\n\nThis painting... my daughter, Andrea... she loved to... to paint...", objectives = "Travel to the farm house in Gahrron's Withering and gather any mementos you can find.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27019] = { id = 27019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge of the Downs", description = "Outstanding!  My name is Belnistrasz, and I thank you for rescuing me.  I had given myself up for dead... or worse, as a meal for these Scourge-infested vermin.\n\nListen... rather than just flee, I want to make a difference for all of our sakes.  Would you be up to helping me out to that end?  It's probably dangerous, but somebody needs to do it and I seriously doubt other adventurers will wander into this desolate place.", progress = "I'm not one for politics; I care not if your affiliations are for either Horde or Alliance.  I am more interested in squelching direct and dire threats to all the races... and we have quite a large one in here.\n\nIf you're willing to be a true hero for all people, then hand me the oathstone I have given you as a sign of commitment.  I'm... not from around these parts; an oathstone is important to people of my kind as a bond of agreement.", completion = "Fantastic, I thought you looked to be the heroic type!  We've got our work cut out for us {name}, I'm not going to lie to you.  If we stay focused on the task at hand, we should be able to come out on top.", objectives = "If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27020] = { id = 27020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Lesson", description = "You have done well. As you continue along your path, you will grow, learning new techniques that you couldn't have imagined before.\n\nYour first lesson is the power of experience. Go, learn a new ability, and demonstrate it for me.", completion = "You have done well, {name}. Return to me when you are in need of further training.", objectives = "Reach level 3 to learn Charge. Locate a Training Dummy in Camp Narache and practice using Charge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27021] = { id = 27021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "It is time for your first lesson, {name}. You have a long way to go to master the ways of the hunter, but as you complete more of your journey, you begin to take new steps on that path.\n\nGo, get more experience, and figure out a new ability. Then, use it on the training dummies here.", completion = "You have done well, {name}. Return to me when you are in need of further training.", objectives = "Reach level 3 to learn Steady Shot. Locate a Training Dummy in Camp Narache and practice using Steady Shot 5 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27022] = { id = 27022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extinguishing the Idol", description = "Near the entrance is an idol that functions as a macabre oven for the Quilboar; they...they literally consume their abductees from the Barrens.  I can shut down the idol and render it useless, but I need your aid in doing so.  My plan: escort me to the idol.  Once we arrive, I'll commence the ritual.  I'll barely be able to communicate with you, let alone defend myself.  Protect me while I shut down the idol.\n\nAre you with me, {race}? Can I count on you to help me end their atrocities?", completion = "Belnistrasz's sudden departure has left behind a burning brazier.  As you stare in to the flame, the image of a great-winged red dragon fills your mind.  A more graveled version of Belnistrasz's voice speaks directly to you.\n\n\"Indeed mortals, you are the heroes I had hoped you would be.  Thanks to you the butchery these beasts were perpetrating is a thing of the past.  My faith in your kind has been once more renewed.  Take this as a reward befitting of a hero.\"", objectives = "Protect Belnistrasz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27023] = { id = 27023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way of the Sunwalkers", description = "It is always a pleasure to meet a fellow Sunwalker. We are not as numerous as some of the more ancient orders, but our ways are no less powerful and our members no less respected.\n\nAs you continue on your journey, you will grow closer to the light and gain abilities you couldn't have imagined.\n\nGo, get more experience, and return when you've learned a new ability. Demonstrate it to me.", completion = "You have made me proud, {name}. You will make a fine Sunwalker. Return when you desire further training.", objectives = "Reach level 3 to learn Seal of Command. Locate a Training Dummy in Camp Narache, cast Seal of Command on yourself and hit the dummy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27024] = { id = 27024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Partners in Crime", description = "Although Amnennar is the primary threat here, he is far from the only. You need to slay his lieutenants as well if their hold on the Downs is to be released.\n\nGlutton guards the beginning of the Spiral of Thorns.\n\nMordesh stands atop The Bone Pile inciting the Scourge into a ravenous frenzy.\n\nTuten'kash resides underground. In order to bring him out, you must strike the gong in The Caller's Chamber three times.\n\nGood luck, brave hero.", completion = "Well done! Without their leaders, the Scourge will pose no significant threat.", objectives = "Kill Glutton, Mordresh Fire Eye, and Tuten'kash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27025] = { id = 27025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thistle While You Work", description = "It's stabthistle season! Stabthistle seeds are responsible for up to 89% of seed-related injuries among hunters.\n\nYou'll find Stabthistle seeds mostly in the lower woodland just north of the lodge. They're commonly found at the base of trees, and they will stab and hurt you.\n\nI'd advise you to avoid them, but I actually need someone to help remove them for the sake of safety! Bring me back Stabthistle seeds so we can make sure others don't get hurt.", progress = "Handle them safely, now!", completion = "I've been informed there's a bear warning active for the woodlands as well! They love those stabthistle seeds.\n\nIt's a good thing you gathered those so they don't attract more bears!", objectives = "Collect 6 Stabthistle Seeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27026] = { id = 27026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defcon: Bobcat", description = "Stop everything! It's come to my attention that there's been bobcat sightings near the lodge. Bobcats!\n\nNow mind you, I've never seen a bobcat, but they're surely dangerous. They're like mountain lions or something. I don't want anyone leaving until the area is secure!\n\nAnyone but you, that is. I'll pay you to help secure the area, {class}. But don't get your face ripped off.", completion = "Okay, yes, I have already been informed that bobcats are much smaller than I was assuming. But that's still pretty dangerous for gnomes!\n\nYou've done a good thing for the safety of this lodge, {name}!", objectives = "Kill 8 Bobcats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27027] = { id = 27027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Strike", description = "I know you've been busy helping the braves protect Camp Narache from the bristlebacks. We're going to need all the hammers and all the luck we can get.\n\nAs your skills increase, so does your connection to the elements. This gives you access to new abilities.\n\nThe first of these that we learn is Primal Strike. It should help you fell your enemies faster. Learn it, and then try it out.", completion = "Well done, {name}. I see you will have no trouble mastering our more advanced arts as you gain experience. Return to me when you need further training.", objectives = "Reach level 3 to learn Primal Strike, and then locate a Training Dummy in Camp Narache and practice using Primal Strike 3 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27028] = { id = 27028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hornet Hunting", description = "We're always looking for new game around here. Daryl may like his boars, but the rest of us prefer things more exotic.\n\nNow, I'd never say the Loch draining was a good thing, but it did have a silver lining. The swampy ground's brought in new prey: Hornets!\n\nGiant hornets, mind you. Not many hunters have tussled with massive bugs before. It's rather novel.\n\nIf you'd like to give it a try, I'll wager with you. Bring me back some of those nice glossy wings of theirs and I'll pay up.", progress = "How go those wasps?", completion = "Lovely specimens you've got there! Here's my wager, lad.", objectives = "Collect 6 Glassy Hornet Wings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27029] = { id = 27029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cure the Scourge", description = "Far more effective than killing swarm after swarm of Scourge is finding a method to prevent living creatures from ever being turned into them. I have an idea for a fine powder that, when inhaled, may stop the entire process.\n\nI need withered tusks off the unliving Quilboar here to make this powder. Bring me an ample amount, and we may be able to stop the Scourge's growth for good.", progress = "Do you have the tusks?", completion = "I have faith that this substance will prevent many future headaches. Thank you, {class}.", objectives = "Collect 20 Withered Tusks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27030] = { id = 27030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foxtails By The Handful", description = "We've seen more foxes in the hills lately. Cunning creatures, they are. A good test of a hunter's skills, and a fine profit to boot!\n\nIt's their tails, <lad/lass>. Fine and fluffy, they're just as good hung on yer belt to ward off fleas as they are to line the gloves of some fancy noble.\n\nListen to me prattle on. I'm no goblin; the thrill's in the hunt! But if you bring me back some foxtails, I'll still gladly pay you for 'em. You'll find the foxes just north of the lodge in the lower woodlands.", progress = "What've you got for me?", completion = "Ahh, you see? Goods of the finest quality. Good work gettin' these.", objectives = "Collect 7 Fluffy Fox Tails.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27031] = { id = 27031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wing Nut", description = "I'm through with gyrocopters. Sure, they work, but when has that ever been good enough for a real gnome? I want real flight, with WINGS!\n\nI've been studying birds for years now, trying to unlock the final secret to building a machine that flies just like them. That elegant soaring and swooping, the rush of wind over the wings, ahh.\n\nYou! You can help me. I need the finest flight feathers you can find. The golden eagles circling near the lodge would be a fine choice...", progress = "Only the finest feathers will do!", completion = "Beautiful. you've got an eye for quality!\n\nGreat minds think alike! It's clear you've got an enthusiasm for flight and fowl, so maybe you can help me further...", objectives = "Collect 3 Pristine Flight Feathers from Golden Eagles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27032] = { id = 27032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bird is the Word", description = "I've actually nearly perfected my dream machine: The Skystrider! The world's first flying Mechanostrider! But, well\n\nWhen I was putting the finishing touches on it in my secret cavern lab, my other creations became, er, jealous. Giving mechanical birds a personality to begin with was probably a bad idea, but that's already done.\n\nI need the Supermechanical Robo-Widget from the original Skystrider if I want to rebuild it! Please, journey into the cave and retrieve it for me!", completion = "<The Skystrider sits silent, its chance to fly gone. An obvious hatch on the front is marked \"SRW\".>", objectives = "Find the Rusted Skystrider inside Ironwing Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27033] = { id = 27033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skystrider's Heart", description = "Opening the hatch, you find an imposing looking mechanical device hooked to several wires, gears, and who knows what else.\n\nIt's easily detached. Time to bring it back to Bingles.", completion = "Perfect! Now that I've perfected the wing balance and have all the parts I need, all we need is a pilot.", objectives = "Return the Supermechanical Robo-Widget to Bingles Blastenheimer at the Farstrider Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27034] = { id = 27034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He's That Age", description = "I'm not making the Skystrider for me, {name}. Not even for gnomekind. I want my son to be the one to fly it.\n\nI'm old, and my reflexes aren't what they used to be. But my boy Ando could be the best pilot Azeroth's ever seen, if he'd just get over his teenage moodiness!\n\nHe sits out by the loch, staring at the sky all day. Something's been bothering him, and yet he refuses to talk to his own father about it. I'm at a loss!\n\nPlease, {name}, could you go talk to him? Tell him I need him to pilot the Skystrider!", completion = "I don't care about my father and his silly inventions! It's all just nonsense!", objectives = "Speak to Ando Blastenheimer on the east side of the Loch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27035] = { id = 27035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standing Up", description = "Look at them. The Twilight's Hammer ruined this land!\n\nThat cult caused this Cataclysm, and broke the Stonewrought Dam, and drained the entire Loch. And now they wander around the ruins like it's their home!\n\nIf there was any justice in this world, someone would march into their camp and break that artifact of theirs in half. But I'm too weak to even try it.\n\nAnd nobody else is brave enough either! Not even you! You see? It's all so stupid...", progress = "See what I mean? You don't even care either.", completion = "You did it? You did! You fought them and won!\n\nThere's hope after all...", objectives = "Destroy the Twilight Landshaper at the center of the Twilight's Hammer Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27036] = { id = 27036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyrin's Revenge", description = "I don't suppose you'd be interested in a little payback for His Boldness? Daryl does have some skill, it pains me to say.\n\nA year ago, a large bear had been the target of the Farstrider Lodge, but none of the hunters had any luck with him. So, Daryl thought he'd try his hand against him. All he had to show for his effort was that ugly scar over his eye.\n\nKill the bear, and I'm sure even Daryl would be speechless for once.\n\nThe bear, Ol' Sooty, can be found around his lair in the cave to the north.", progress = "Ah, {name}! Back so soon? No doubt you've been at the hunt again? Don't worry if you've had some setbacks, in the long run it will make you better!\n\n...You couldn't get much worse, anyway...", completion = "Er... what's this? A bear's head, by the looks of it.\n\n<He runs a finger along his scar unconsciously.>\n\nWell, that's quite an interesting kill you have yourself there. Couldn't be that bear from back then...\n\n<He trails off then starts to visibly shake.>\n\nOh, take that away take it away! Get that grisly thing out of here!", objectives = "Kill Ol' Sooty and obtain his head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27037] = { id = 27037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyrin's Revenge", description = "Light! Don't bring things like that into the Lodge... it's unsanitary, unspeakable, un... un... unsanitary!\n\nJust get it out of here, will you? No one wants to see your bloody little trophy, really!", progress = "Great job, {name}! We really showed him! Here, give me the head and I'll take care of it.", completion = "Thanks for helping me out with my little plan, {name}. I've been itching for months to get back at that snooty, stuck-up boy, and I'd say we did a pretty good job! Here, have this, you've earned it.", objectives = "Bring Ol' Sooty's head to Vyrin Swiftwind at the Farstrider Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27038] = { id = 27038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Parts", description = "<The Sergeant turns his attention to you.>\n\nLook here, if you want to help speed things up around here, get Flintlocke off my back. A whole shipment of siege engine parts was misplaced and now it's scattered all up and down the dock.\n\nGather up the missing parts and get them to Flintlocke so he can finish construction. He's just across the road from me, waiting.", progress = "Eh wot?\n\nMy parts. Where are they? You can't build a tank without parts!\n\nIf yeh did, it'd be small. An' mostly inner-fectual.", completion = "<Flintlocke greedily digs through the machine parts, tossing choice picks over his shoulder.>\n\nOh aye, 'ere's the stuff.\n\n<He sticks his head all the way into one of the crates.>\n\nBut where's me powder? Everything's here but for the powder. I need explosives, man!\n\nYou tell the King, no powder, no power. I need me some kersplosions or I ain't leavin' port.", objectives = "Gather up 5 Missing Parts from around the Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27039] = { id = 27039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Intentions", description = "Do you know why Mortuus appends 'nub' to your name, {name}? Because he is an incompetent sycophant that has trouble seeing through his oversized helmet. 'NUB' is your classification. You are now part of the NEW UNDERCITY BATALLION.\n\nBut enough with the comedy! I sent Deathstalker Yorick on a shadow operation two days ago. Her goal was to get information on the Gilneas Liberation Front and return. Three days and no word from her.\n\nHead southwest to the Ivar Patch and look for Yorick, {name}.", completion = "Belmont gets a little nervous and sends some newbie to look for me? Listen, I've been staking out the old Ivar cottage from inside this outhouse for three days. Your presence threatens the whole damn operation!\n\nThere's no time to explain. We have to act now or this mission will be compromised.", objectives = "Find Deathstalker Yorick at the Ivar Patch in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27040] = { id = 27040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decryption Made Easy", description = "We don't have the tools to decipher these encrypted plans. The Twilight's Hammer do, though.\n\nWould you be a sweetie and take the plans back up there to run them through their one-time decryption engines?", objectives = "Decrypt 6 plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27041] = { id = 27041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decryption Made Easy", description = "We don't have the tools to decipher these encrypted plans. The Twilight's Hammer do, though.\n\nWould you take the plans back up there and run them through their one-time decryption engines?", objectives = "Decrypt 6 plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27042] = { id = 27042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Fire and Water and Air with...", description = "Did ye hear the blatherin' idiot while ye were up there? That's none other than Haethen Kaul, their leader.\n\nThe man's gone daft with power. He's pullin' it straight from them bound elementals, makin' him nigh invincible.\n\nThe only thing I can think of to get ye into proper shape fer a fight with him is fer ye to first kill all o' them elementals, gettin' their wards. That should protect ye from Haethen's spells.\n\nWell, most o' them anyway.", completion = "That's the ol' spirit! One less nasty in this world that the little ones will have ta worry about when they go ta sleep at night.\n\nNot ta mention that we won't have ta be worrying about him none no more neither!\n\nNow let's see here. I think we have somethin' in our crates that'll make a fittin' reward fer ya.", objectives = "Acquire the Fire, Water, and Air Wards, and then slay Haethen Kaul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27043] = { id = 27043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Fire and Water and Air with...", description = "Did you hear the man going on with his incessant yelling while you were up there? That's Haethen Kaul, their leader.\n\nIt's a well known fact that he's gone insane from the power he's drawing from their bound elementals. Unfortunately, it makes him nigh invincible.\n\nIf you're to fight him, you'll first have to kill each of the elementals, gaining their wards in the process. That should protect you from Haethen's magic.\n\nWell, most of it anyway.", completion = "An excellent display of {class} prowess.\n\n\n\nI believe that a reward is in order. Something appropriate for a powerful man such as yourself.", objectives = "Acquire the Fire, Water, and Air Wards, and then slay Haethen Kaul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27044] = { id = 27044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peasant Problems", description = "I'm not quite ready to go back to the keep yet. Would you like to help me with something?\n\nRecently some of the local farmers were petitioning the King about some missing livestock. My father promised someone would investigate, but the city guard is stretched so thin it'll take weeks.\n\nI thought I would help! It'll encourage the farmers to see someone take action, especially from the royal family. Besides, it's just some missing cows. Nothing dangerous.\n\nTake me to Farmer Wollerton here in the city!", completion = "<On seeing the Prince Regent, Farmer Wollerton collapses awkwardly down on one knee.>\n\nY- Y- Your highness!", objectives = "Escort Prince Anduin to Farmer Wollerton at the Wollerton Stead within Stormwind City. If he's no longer with you, you can find him in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27045] = { id = 27045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waiting to Exsanguinate", description = "The Gilneas Liberation Front leader, Darius Crowley, has been meeting with another worgen inside this cottage for the past three days. I'm not sure what's going on, but we need to get inside the cottage and find a good hiding place from where we can eavesdrop.\n\nIt's now or never, {race}. We may never get another shot.\n\nJust promise me that if I don't make it, you'll return to Forsaken High Command and inform Belmont of whatever we discover.", completion = "Alas, poor Yorick! I knew her, {name}. An assassin of infinite courage...\n\nNow, tell me what's going on? What did you and Yorick discover?", objectives = "Enter the Ivar Cottage and find a suitable hiding place upstairs. Then eavesdrop on Lord Darius Crowley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27046] = { id = 27046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fear of Boring", description = "The gyreworms infest the rock, eating away at it until our home will one day collapse. For every one that is killed, twice as many burst forth to follow, but we must carry on the fight. They must be extinguished.\n\nGo to the Crumbling Depths and slaughter any worms that you can find.", progress = "Your flesh is well suited for the task. It does not corrode from their attacks as our rockskin does.", completion = "You wage a war that we cannot. Thank you for your help.", objectives = "Kill 10 gyreworms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27047] = { id = 27047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Motes", description = "Some of the rarest crystals form in the most dangerous places. In the Crumbling Depths, you will find painite formations - much better than the gold that your races cherish so much.\n\nAs a being of flesh and a being of small stature, you can enter the Crumbling Depths to retrieve motes of painite for me. Would you undergo that danger on my behalf?", progress = "Painite is one of the most valuable materials to us, particularly due to our inability to reach most of the deposits on our own.", completion = "Well done, {race}. These will do well.", objectives = "Recover 10 Motes of Painite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27048] = { id = 27048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Underground Economy", description = "Hey! I need some help gatherin' crystals. The elementals trade top dollar for these things... if you help me gather all the different kinds, I'll cut you in on the profits.\n\nUse these bombs to blow out chunks from the bigger formations.\n\nI've got a nasty habit of packin' the explosives a bit thick. Mind the kick.", progress = "Boom?", completion = "Well played!\n\nI've got this pretty sweet deal going. A bunch of shmucks go up there to Therazane's Throne and give all kinds of gold to D'lom for who-knows-what kinda crap. He forks all that cash over to me for these crystals. I go home freakin' rich for a couple chunks of rock.\n\nDon't tell no one though. I don't want no competition springin' up.\n\nThink you can come back later to help me get another load of crystals out?", objectives = "Use Ricket's Tickers to gather 3 Deep Alabaster Crystals, 3 Deep Celestite Crystals, 3 Deep Amethyst Crystals, and 3 Deep Garget Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27049] = { id = 27049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soft Rock", description = "The corruption of the Crimson Expanse has not subsided. Destroy the Fungal Behemoths that shower their filth upon our realm. If they continue to rise, we will continue to destroy them.", completion = "Once the growth starts, it is near impossible to stomp back into submission. Through persistence our realm will one day be cleansed.", objectives = "Kill 8 Fungal Behemoths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27050] = { id = 27050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungal Fury", description = "Something upon the Crimson Expanse continues to spur disgusting growths upon the rock. New fungi are rising, and they need to be crushed before they can spread.", completion = "You are proficient at stepping on things. You would make an excellent giant.", objectives = "Destroy 10 of the newly sprouted mushrooms in the Crimson Expanse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27051] = { id = 27051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through Persistence", description = "The troggs did not disperse after you killed Glop. His servants recovered the growth agent that was left behind and continue to sow the seeds of corruption across the Crimson Expanse.\n\nHunt them down and recover any of the remaining Verlock Miracle-Grow that you find. It must be disposed of.", progress = "Have you done as I've asked of you? We must weed out the whatever growth agent remains within their possession.", completion = "Thank you, {race}. We will weed the rest out of their possession in time.", objectives = "Retrieve a Bag of Verlok Miracle-Grow from the Verloks upon the Crimson Expanse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27052] = { id = 27052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lingering Twilight", description = "Twilight drake riders remain in Deepholm. They are scattered. Defeated. Yet they remain.\n\nTake wing with Aeosera's flight and hunt them down. The stone drakes await you on the ledge to the southeast.\n\nWe will destroy every last one of the Twilight. In the Stonemother's name.", objectives = "Hunt down a Twilight Drakerider on a Crystalwing Stone Drake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27053] = { id = 27053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gahrron's Withering Cauldron", description = "My analysis is complete!  The blight that affects the animals here is no residual disease.  No, it is something new... and I think I know what it is.\n\nThe Cult of the Damned maintains a plague cauldron on a farm called Gahrron's Withering.\n\nThis farm is due southeast of us, close to where the Eastern Plaguelands begin.  I need a sample from this cauldron to verify my suspicions.\n\nEliminate the cauldron lord present there for its key.  You will then be able to access the cauldron and obtain my sample.", progress = "An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.", completion = "Cauldron Lord Soulwrath's key disintegrates as it touches the lock on the access panel at the base of the cauldron's platform.  A slight clanking noise is heard within, and the access panel swings open to reveal more viscous toxins within the cauldron's framework.\n\nThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for Field Agent Kaartish back at the Menders' Stead.", objectives = "Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27054] = { id = 27054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Acts", description = "The Cult of the Damned maintains a small camp to the east, Malicia Outpost, which they use for field training outside of the Scholomance.  We may have allowed them to proceed unchecked with this training for too long.\n\nIf cultists are truly using this plague to inoculate the wildlife, then Malicia Outpost must be where the inoculation is occurring.\n\nInstructor Malicia runs the outpost.  Find her, slay her, and find out who she's taking orders from.", progress = "You take a look at the paperwork Malicia was carrying...", completion = "The orders in Malicia's possession incriminate Darkmaster Gandling of the Scholomance, but they also conceal another important bit of information.", objectives = "Kill Instructor Malicia and obtain her Cult Orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27055] = { id = 27055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Students of Krastinov", description = "The Cult orders state that the plague from the cauldron at Gahrron's Withering is in fact being used for TWO purposes.  The first is the practice of spreading disease through the animals of the plaguelands, which you already knew about.\n\nThe remainder of the plague is being shipped to the Weeping Cave, a cavern north of Malicia's Outpost, for use in some dark experiments.  Students of the Scholomance are using this plague to re-animate the dead!\n\nCertainly they must be stopped.", progress = "How is your investigation proceeding, {name}?", completion = "You have gone above and beyond, {name}.  Not only have we set back the Cult of the Damned in their crusade to re-plague the plaguelands, but you have uncovered another set of dire plans: they continue to re-animate the dead!\n\nYour name will definitely be mentioned when this information is presented to Highlord Fordring, {name}.  You have my thanks, and the blessing of the Argent Crusade.", objectives = "Kill 2 Krastinovian Disciples, 2 Flesh-Cobbled Brutes, 2 Flesh-Cobbled Rippers, and 4 Unholy Corpuscles within the Weeping Cave in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27056] = { id = 27056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belmont's Report", description = "<Belmont hands you a sealed envelope.>\n\nDeliver this report to Lady Sylvanas Windrunner. It is my assessment of the situation in Silverpine based upon your and Yorick's field work.\n\nIf we do not stamp out the worgen insurgents, they will overrun us. The time to act is now!", progress = "Kneel before your queen, {name}.", completion = "Crowley... A gnat. An insect, waiting to be crushed beneath my boot heel.\n\nSo he thinks to rouse the feral worgen of Silverpine? We shall show him and his allies the might of the Forsaken!\n\nBut first we must clean up the mess made by the Warchief's fleet. Without their aid we may lose this war.", objectives = "Deliver Belmont's Report to Lady Sylvanas Windrunner at Forsaken High Command in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27057] = { id = 27057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Stead", description = "You carefully close the spigot in the control panel, watching the cauldron's putrid ichors drip into the empty bottle.\n\nWith the poison in hand, it is time to return to Field Agent Kaartish at the Menders' Stead.", progress = "Gahrron's Withering houses a viciously potent plague cauldron.  Once we have a sample of the plague it spews forth, we will be able to determine whether the Cult of the Damned is truly responsible for continuing to poison the land.", completion = "Good work.  One moment please...\n\n<The draenei takes a moment to compare your sample with a sample he presumably had distilled earlier.>\n\nYes, this appears to be the same corruption that is affecting the wildlife.  With this knowledge, and with your combat expertise, we may have the power to stop this.", objectives = "Bring the Filled Gahrron's Withering Bottle to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27058] = { id = 27058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrong Sequence", description = "The Twilight's Hammer must be stopped from using the Waygate. There's only one thing to do.\n\nPunch in the wrong activation sequence and destroy it.\n\nHmm, let's see. Yes, here's one that opens upon the explosive depths of the Firelands, the elemental plane of fire. That should do nicely.", completion = "You did it! You found out what the Twilight's Hammer were up to and you stopped them dead in their tracks!\n\n<Mowi gets up on her tippy toes and gives you a kiss on the cheek.>\n\nNow I'm certain that I have something around here for you.\n\n<She begins rummaging around for your reward.>", objectives = "Use the Waygate Controller to punch in the wrong activation sequence, thereby destroying the Waygate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27059] = { id = 27059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrong Sequence", description = "The Twilight's Hammer must be stopped from using the Waygate. There's only one thing to do.\n\nPunch in the wrong activation sequence and destroy it.\n\nHmm, let's see. Yes, here's one that opens upon the explosive depths of the Firelands, the elemental plane of fire. That should do nicely.", completion = "You did it! Excellent work, my boy. You found out what the Twilight's Hammer were up to and you stopped them dead in their tracks!\n\n<Examiner Rowe pats you on the back with his bony hand.>\n\nNow I'm certain that I have something around here for you.\n\n<He begins rummaging around for your reward.>", objectives = "Use the Waygate Controller to punch in the wrong activation sequence, thereby destroying the Waygate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27060] = { id = 27060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unholy Cow", description = "<Farmer Wollerton tries to pull himself together.>\n\nCows? You're asking about the missing livestock?\n\nI normally just let the cows graze north of the house here. Occasionally one gets spirited away. Leaves a trail of gore. Who would do such a thing?\n\nI'm afraid to follow that trail myself... something sick is happening in Stormwind!", completion = "That was a close one! I can't believe you stood your ground against so many at once.\n\nIt looks like this site was used for some kind of twisted Twilight's Hammer initiation ritual. They're definitely active in Stormwind. What's this?\n\n<Anduin finds a badge resting on the shrine.>\n\nThis badge shows a crossed axe and hammer. It looks old. If we keep poking around, we might figure out what it means...", objectives = "While escorting Anduin Wrynn, follow the trail of gore from Farmer Wollerton's Stead to the crime scene. Keep Anduin alive. If he's not with you, he will be waiting in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27061] = { id = 27061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Overlook", description = "The dragon they're speaking of is Abyssion, {name}.  It's not going to be easy to get the fragment off of him.\n\nMeet with Mylra again.  She is operating nearby at the Twilight Overlook.\n\nShe will tell you what our next move will be.", completion = "So we're going to have to take on Abyssion to get the fragment?  This operation just got a whole lot more difficult all of a sudden.", objectives = "Speak to Stormcaller Mylra at the Twilight Overlook in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27062] = { id = 27062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looming Threat", description = "The Quilboar in Razorfen Downs seem to have allied with the Scourge. This is dark news for us, {class}. We have dire enough problems dealing with these Grimtotem, we won't be able to handle an attack by the Scourge. Venture into Razorfen Downs, east of here, and see if you can find anyone that may be able to help you stop them before they decide to attack here.", completion = "You seem an able warrior. Perhaps you can help me put an end to the terrible evil here.", objectives = "Find help in Razorfen Downs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27063] = { id = 27063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looming Threat", description = "The Scourge are a direct affront to nature. They have managed to corrupt the Quilboar in Razorfen Downs and now threaten to spread further into Thousand Needles and eventually, I fear, west into Feralas. You must go there and do anything you can to confine them. Perhaps you can find someone in the area to help you? The winds whisper of a powerful presence in the area.", completion = "You seem an able warrior. Perhaps you can help me put an end to the terrible evil here.", objectives = "Find help in Razorfen Downs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27064] = { id = 27064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He's Holding Out on Us", description = "{name}, it almost seems like Samuelson is trying to intentionally waste your time. The dockworkers don't know anything. More importantly, explosives are missing from Stormwind Harbor!\n\nYou know what I think? I bet Samuelson knows more than he's letting on. He probably has a lead on Twilight's Hammer and wants all the credit and glory for himself.\n\nWe should peek through his records at the SI:7 headquarters. Take me there and I should be allowed to look at his files and find out what he really knows.", completion = "This is REALLY suspicious, {name}! Samuelson doesn't have a shred of info here about the Twilight Hammer - it's almost like he's not investigating them. Yet he's got a complete catalog of the missing explosives.\n\n\n\nAnd I found this funny badge with a symbol on it: A crossed axe and hammer.\n\nIt all means something, but what?", objectives = "Escort Anduin Wrynn to the third floor of SI:7 Headquarters in the Old Town district of Stormwind. If he is no longer with you, you can find Anduin in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27065] = { id = 27065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief's Fleet", description = "Our reinforcements from Kalimdor arrived last night. Three orc gunships full of supplies, weapons and soldiers. Three orc gunships lost to Bloodfang's damned worgen.\n\nHow could an entire orc fleet lose to a small band of enemy combatants that lack any siege weaponry? An important question that you will answer for me.\n\nGather your gear and report to the orc admiral, Hatchet, at the Forsaken Rear Guard, southwest of here.\n\nGet those orcs operational, {name}.\n\nI await your full report.", completion = "This fiasco may go down as one of the biggest embarrassments in the history of naval warfare. How did this happen? Drunk happened. That's how.", objectives = "Report to Admiral Hatchet at the Forsaken Rear Guard in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27066] = { id = 27066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Word", description = "As you become more skilled, your skills will expand, and you will gain access to many new powers.\n\nGo - get some experience out there, and come back to me when you've learned something new. You can demonstrate on the training dummies nearby.", completion = "Thank you for your help in seeing to the wounded braves. I'm sure that you will often find your healing skills in demand. Return to me when you need further instruction.", objectives = "Reach level 3 to learn Shadow Word: Pain. Practice using it 5 times on Training Dummies in Camp Narache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27067] = { id = 27067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonfire", description = "As you develop your skills, druid, you will begin to feel your connection to the Earthmother deepening. You will begin to understand new secrets of nature, and learn to cast new spells.\n\nGo now, get more experience, and return to me when you've learned a new spell. Demonstrate what you've learned.", completion = "You have a knack for the healing arts, {name}. Wherever you go, your skills as a healer will be in demand. Return to me when you are ready for more training.", objectives = "Reach level 3 to learn Moonfire. Practice using it on a Training Dummy in Camp Narache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27068] = { id = 27068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chief Ukorz Sandscalp", description = "Take a good look, mon. Dis is how it goes, betrayal after betrayal. I backstab you for the sword, and den Chief Ukorz go and backstab me even better for it.\n\nThat's life, yah! Or was...\n\nNow, I know you don't got no love for Mazoga. But I know you goin' in der anyway. Kill him for me, mon. Spill more blood on the sand, an' give Chief Ukorz Sandscalp what every one of de Sandfury deserves...a gory death.\n\nMaybe I leave some of my belongin's without a curse before passin' on if you do, yah?", completion = "He's gone? Did he have the sword?\n\nNah...don't tell me. Don't matter no more. Mazoga don't care.\n\nI'm off now, mon. De consequences of my actions await me. Take whatever I was holdin'... I don't need it where I'm goin'...", objectives = "Kill Chief Ukorz Sandscalp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27069] = { id = 27069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steel Thunder", description = "We may not have to live down the shame of this defeat, {name}. The Warchief will likely have us all executed instead.\n\nI'll be damned if we don't go down without a fight. Although the whole beachhead is overrun by Bloodfang worgen, there may still be hope. I want you to accompany one of our sea pups to the beachhead, directly west of here, and recover our supplies. Return to me when the pup can carry no more.", progress = "The pups might be the only orcs not drunk at this base.", completion = "Within these crates are held STEEL THUNDER! With our weaponry returned we might have a chance to redeem ourselves.", objectives = "Recover 5 Sea Dog Crates.\n\nSpeak with Admiral Hatchet to get another Orc Sea Pup if you unexpectedly lose yours.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27070] = { id = 27070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fool's Errand", description = "I heard that a troll in here, Hydromancer Velratha I think she was called, has come into the possession of a very rare, beautiful, and powerful piece of jewelry called the Tiara of the Deep. She uses it to control the powerful demigod Gahz'rilla, whose very scales are said to crackle with energy. Do you know what all of that means, {race}?\n\nI need it! Kill Velratha, take the Tiara of the Deep, and kill Gahz'rilla for one of his scales. Bring them all back to me pronto! I'll reward you handsomely.", progress = "Do you have what I need?", completion = "Excellent! This Tiara will grant me complete control of the water around here, and the Electrified Scale will serve to power all the machines I need to use it all to my advantage!\n\nYou're going to make me a very rich and powerful goblin! You can have this, it's nothing compared to what I'll have soon.", objectives = "Obtain the Tiara of the Deep and Gahzrilla's Electrified Scale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27071] = { id = 27071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Sandfury", description = "De Sandfury are a resilient tribe. Dey have survived sandstorms an' years an' years of other tings long covered by da sands. It would be foolish to assume that the only forces here are da trolls. We been tamin' da scarabs, breedin' da sul'lithuz, an' raisin' our dead to keep on fightin' for all eternity as zombies.\n\nRuuzlu, da right hand of Chief Ukorz Sandscalp, be plannin' to use dem to retake Tanaris for de Sandfury empire. You best be killin' da trolls in charge of dis if you want to live, mon.", progress = "If dey ain't dead yet, you can't guarantee your own life, {race}.", completion = "You killed dem? All of dem? And you return alive?\n\nTake what you want off my body, den. It's mostly curse-free, Mazoga promises.", objectives = "Kill Theka the Martyr, Witch Doctor Zum'rah, Antu'sul, and Ruuzlu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27072] = { id = 27072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Old Barracks", description = "I recognize the symbol on these badges from before Deathwing's attack on the city. It belonged to soldiers in the old barracks, west of town overlooking the harbor.\n\nYour timing couldn't be better. One of my top agents, Jack Bauden, has been trying to infiltrate the Twilight's Hammer cult for me. Last night he went missing. If you and Anduin are right, the cultists are holed up in the old barracks. Time is urgent! Assault the old barracks, take out those cultists, and rescue Jack Bauden.", completion = "<You slap Bauden around until he wakes up.>\n\n{class}? What are you doing here?\n\nI'm SI:7 Agent Jack Bauden. This is the longest day of my life.", objectives = "Go to the Old Barracks and slay 6 Crazed Cultists, then locate Jack Bauden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27073] = { id = 27073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give 'em Hell!", description = "It's the goblins' fault, {race}!\n\n<hic!>\n\nYou see, we set off for Silverpine from Bilgewater Harbor, over in Azshara. Huge mistake that was! Never has such a den of inequity and sin existed in our great empire. Those damnable goblins fueled our every vice and set us off to sail with barrels full of ale. \n\n<hic!>\n\nThe shame of it all leaves a mark greater than any scar. Honor must be restored! Kill the Bloodfang worgen that ambushed us. They're scavenging the wreckage to the southwest.", progress = "Give 'em hell, {race}!", completion = "Looks as if you really gave those worgen a beating and, in the process, lifted the \"shame haze\" they cast over us. Perhaps the sea dogs will quit drinkin' now.\n\nWho am I kidding?\n\nHah!", objectives = "Kill 10 Bloodfang Scavengers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27074] = { id = 27074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight the Hammer", description = "You've done what I thought was impossible! I'm done moping around here. It's time to gnome up.\n\nI've got to find my father. But you! Don't bother yourself with me any longer. You've got to keep fighting these cultists.\n\nGo talk to Ashlan Stonesmirk to the east. He's trying to stop the Twilight's Hammer, but he has nobody to help him. You're his only hope!\n\nDon't give up, {name}. I won't.", completion = "You hit the twilight camp at the center of the lake? Not bad, lad!\n\nIf you're ready to take the fight right to their doorstep, I've got your chance.", objectives = "Talk to Ashlan Stonesmirk near Mo'grosh Stronghold in Loch Modan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27075] = { id = 27075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Servants of Cho'gall", description = "The Twilight's Hammer started as a clan of the savage Horde. Their leader, Cho'gall, slowly turned his band of ogres into a death cult, welcoming anyone insane enough to wish for the end of all existence. As you can see, there's still plenty of ogres among their ranks; deranged, fanatical, and just as strong as before.\n\nThese crude monsters have the gall to come here and spread their filth across our land. The more you kill, the better off Loch Modan will be, {name}.", completion = "It may look grim, but we'll win with your help, {name}. They won't keep the dwarves down.", objectives = "Kill 7 Mo'grosh ogres in the Mo'grosh Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27076] = { id = 27076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking and Entering", description = "A good buddy of mine, Weegli Blastfuse, joined up with Sergeant Bly and his group of outcasts to invade Zul'farrak and claim the legendary Sul'thraze as their prize. Of course, they underestimated the Sandfury tribe and now they're all trapped awaiting execution to please their demigod, Gahz'rilla!\n\nIf you free him, he'll help you blast your way to Ukorz's private chamber where he keeps at least part of the blade.\n\nKill his captors, Nekrum Gutchewer and Shadowpriest Sezz'ziz as revenge...I'll repay ya.", progress = "Are Nekrum and Sezz'ziz dead? If they are, I know Weegli will be here any minute now.", completion = "Wow! I knew I could count on you! Here's something for your troubles.", objectives = "Free Weegli Blastfuse and kill Nekrum Gutchewer and Shadowpriest Sezz'ziz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27077] = { id = 27077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clutching at Chaos", description = "The cultists of the Twilight's Hammer use their powers to draw elementium metal from deep beneath the earth. They coax it out into twisted spikes to form their buildings, rooted right into the defiled ground.\n\nThe ogres here seem to be in the middle of weaving the stuff, and we need to strike while they're still twisting it into shape.\n\nTear the spikes right out of the ground while they're still pliable, and bring them back to me! We're not going to give these curs a single inch of our land.", progress = "Did you tear up the spikes?", completion = "Shame that these half-formed things are too brittle and warped to be used for some weapons of our own. But it's thanks to you that we had the chance to get them out before they set. I'm not about to complain.", objectives = "Pull up 10 Nascent Elementium Spikes from the ground of the Mo'grosh Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27078] = { id = 27078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gor'kresh", description = "The ogre left to watch over these crude fools goes by the name of Gor'kresh. He's big enough to boss even these brutes around, and cunning to boot. Never assume an ogre's stupid, that's when they'll get you.\n\nIf you take him out, we'll show the Twilight's Hammer that Loch Modan isn't a stepping stone for them. Stand strong against Gor'kresh and drive these fools back into the highlands!", progress = "You can do it, {name}.", completion = "You've done it! We may not have stopped the cult dead, but we've shown them we're not easy pickings and given them a welt to prove it.\n\nTake this with my gratitude, and try not to blush if anyone in Thelsamar calls you \"hero\"!", objectives = "Defeat Gor'kresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27079] = { id = 27079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Gate Tracking" }
quests[27080] = { id = 27080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Gate Tracking" }
quests[27081] = { id = 27081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "rusting the Traitor", description = "These two are useless. Can I at least count on you to get some work done around here, young adventurer? We've come into contact with Mazoga, a traitor to the Sandfury. He says he can help us find the legendary blade Sul'thraze so we can use it to kick out the Sandfury forever!\n\nWe'll probably sell it afterward to the highest bidder, honestly. This place doesn't pay for itself. Go do what he wants...just keep an eye on him. A traitor's a traitor all the same. He's at our camp just east of Zul'Farrak.", sourceObjective = "Speak with Mazoga.", sourceObjectiveStatus = "unverified-source-field" }
quests[27082] = { id = 27082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing Dirty", description = "Have you seen the huge lumbering ettins roaming the forests? Cursed things came from Gilneas. Now they wander the land searching for their next juicy meal. We've managed to subjugate and utilize some of them to haul our wagons, but the others... well, they must be killed!\n\nUnfortunately, we can't spare any soldiers to do the job. That's where you come in, {class}!\n\nI have a plan, but it's going to require some materials. Head out into the forests around this base and collect diseased beast organs.", progress = "We are Forsaken! This is how we do it, {class}.", completion = "Excellent! Now to prepare the \"meal.\"", objectives = "Collect 8 Diseased Organs from Giant Rabid Bears and Rabid Worgs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27083] = { id = 27083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Resumes!", description = "Word is in from Andorhal, {name}.  The battle has resumed.\n\nIt has become somewhat well-known among the Forsaken that you are a hero of the first battle of Andorhal.  Koltira has requested your presence immediately.", completion = "Thassarian and the humans made their move.  I thought I had an agreement with Thassarian... but I suppose this will do.", objectives = "Report to Koltira Deathweaver at Andorhal in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27084] = { id = 27084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Farmers' Militia", description = "The battle started when they attacked us from the rear.  I let my guard down, and a group of poorly-armed farmers and militiamen swung into our flank from the Writhing Haunt.\n\nThey may be weak, but unchecked, they threaten to overwhelm us with their numbers.\n\nLindsay's pet abominations can handle the melee combat.  You take this collar, stay in the rear, and use it to release my ebon gargoyle upon these farmers.", completion = "Merely a dent in their numbers... but the sight of their fellow men falling from the skies surely weakened their resolve.", objectives = "Use the Ebon Gargoyle Collar on 6 Provincial Militiamen within Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27085] = { id = 27085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supporting the Troops", description = "While it is true that these farmers threaten to overrun us, we still cannot forget about the Alliance's main forces.\n\nTravel west into Andorhal and slay the human soldiers that are fighting with our deathguards.  We need all the help we can get.", completion = "You fight well, {name}.  I wish I had your ability... and your bravery.", objectives = "Slay 15 Andorhal Defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27086] = { id = 27086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes to Ashes", description = "To the west, deep within Alliance-held Andorhal, you will find their commanders.  They do not fight, but call out orders from horseback.\n\nHunt down and slay these commanders, {name}.  The humans won't stand a chance.", completion = "Well done.  With them out of the way, I have no more excuses.\n\nSoon, I must battle Thassarian, for honor and for Andorhal.", objectives = "Slay 3 Andorhal Force-Commanders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27087] = { id = 27087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lindsay Ravensun, Revealed", description = "I was informed that that worthless woman, Lindsay Ravensun, would be here to support me in this battle, but so far, she's done nothing but brood within the basement of the greathall behind me.  All the better, I suppose.  She was a bit of a distraction.\n\nStill, I cannot and will not stand for insubordination.  Find her, and bring her to me.", completion = "You won't be taking me anywhere, {name}.\n\nWhile Koltira prances about with his playmate, Thassarian, I plan to win this battle.  Then I'll make Koltira suffer for his weakness.\n\nDon't believe me?  Fine, I'll let you in on a little secret...", objectives = "Report to Lindsay Ravensun at Andorhal in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27088] = { id = 27088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Only Poisonous if You Ingest It", description = "Take this cage, {class}. I've placed inside it one of my own mutant bush chickens, with a few slight modifications. Within the butt of this bush chicken is a stick of dynamite laced with gunk from the diseased organs you brought me.\n\nTake the cage out into the surrounding forest and locate the wandering forest ettin. Release the chicken and sit back as my masterwork does its job. The ensuing explosion should be sufficient to kill the ettin or greatly weaken it, allowing you to finish it off.", progress = "Have you dealt with the ettin?", completion = "<Apothecary Wormcrud laughs maniacally.>\n\nWas there ever any doubt? An ettin is no match for science!", objectives = "Use the Mutant Bush Chicken to kill the Forest Ettin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27089] = { id = 27089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ace in the Hole", description = "You have no idea how difficult it was to stay disguised while I watched Koltira let this war slip away from us.  Even now, those infernal farmers threaten to overwhelm us.  All because he refused to slay a friend.\n\nTake my val'kyr again, {name}.  With her by your side, kill these farmers, convert them to Forsaken, and mobilize them.  Then take a group of them into Alliance-held western Andorhal and hunt down this death knight, Thassarian.\n\nWe will win this war yet.", progress = "This skeleton... what could it mean?", completion = "This is the body of Lurid, Thassarian's trusted knight.  With Thassarian nowhere to be found, it would seem that the Alliance forces have withdrawn.\n\nThe Forsaken have won the battle for Andorhal.", objectives = "With the Enthralled Val'kyr by your side, kill 5 Frightened Provincial Minutemen so that they can be turned into Forsaken Troopers. Then find Thassarian in western Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27090] = { id = 27090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andorhal, Once and For All", description = "Sylvanas will want to know about Thassarian's departure from Andorhal.  You resolve to return to the Forsaken-held side of town.", completion = "See?  All it took was a little help from the val'kyr.  These creatures are turning to be much more helpful than I had first thought.\n\nNow, on to other matters.", objectives = "Report to Lady Sylvanas Windrunner at Andorhal in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27091] = { id = 27091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge!", description = "Good. You are off to a bright start. This road will be long, and as you become more accomplished, you will begin to discover that you can do things you could never have imagined before.\n\nGo, get more experience, and learn a new technique. Once you have, demonstrate it on one of the training dummies.", completion = "I think you've mastered the basics of the charge, {name}. Don't forget to return when you need more training.", objectives = "Reach level 3 to learn Charge. Locate a Training Dummy outside the Sunspire and practice using Charge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27092] = { id = 27092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataclysm in the Catacombs", description = "Don't worry about me, {class}. I've uncovered the Twilight's Hammer plot. They've been stealing and stockpiling explosives coming into Stormwind harbor. Somehow, they've gotten access to the catacombs underneath the Cathedral of Light. I've heard talk of someone called \"The Black Bishop.\"\n\nThere's no time to warn the guard, {name}! You've got just minutes to get into the catacombs and disarm that bomb. Go! Now! Or THOUSANDS of PEOPLE will DIE!", completion = "<3 ... 2 ... 1 ...>\n\n<You wet your fingers and snuff out the fuse. The cathedral is saved!>\n\nUnderneath the powder kegs you find a heap of notes and papers. Apparently the cultists were trying to destroy the evidence behind them.>", objectives = "Enter the Cathedral of Light and descend into the catacombs below. Slay the Black Bishop and disarm the Pile of Explosives nearby.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27093] = { id = 27093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in the Darkness", description = "Some would say that we are lucky to be alive. Those people would be idiots. At least had we died we would not have had to face the Warchief's wrath. Alas, what's done is done! Now we must attempt to regain our lost honor.\n\nThe third ship in our fleet sank off the coast of the Skittering Dark, northwest of here. Those that made it to shore quickly found themselves swarmed by the giant spiders of the area and encased in webbing.\n\nIf there are survivors we must free them! Go, {name}! To the Skittering Dark!", completion = "Lok'tar, {name}! Once the ale wears off my orcs will be ready!", objectives = "Rescue 6 Orc Sea Dogs from the Skittering Dark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27094] = { id = 27094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deeper into Darkness", description = "The Skitterweb matriarch is nearby! You can put an end to the Skitterweb menace by killing her!\n\nFind the brood mother at the end of the cave in the Skittering Dark and destroy her!", progress = "You killed the Skitterweb matriarch?", completion = "You rescued our orcs and killed the Skitterweb matriarch? We owe you a great debt of gratitude. You've saved us all from certain execution, {name}. I'm sure we can rouse these drunken idiots now.", objectives = "Kill the Skitterweb Matriarch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27095] = { id = 27095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skitterweb Menace", description = "Vengeance is all consuming, {name}! Our third ship sank off the coast of the Skittering Dark, northwest of here. The men that made it off that boat were either captured or killed by the Skitterweb spiders of the region. For that, the spiders must die! ALL OF THEM!\n\nTravel to the Skittering Dark and crush those insects!\n\nBe on the lookout for their matriarch. Perhaps if we find her we can end this menace forever!", completion = "The root of this evil must be found and destroyed! The Skitterweb matriarch must be nearby. No doubt hiding in the nearby cave!", objectives = "Kill 12 Skitterweb Spiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27096] = { id = 27096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs are in Order", description = "<Admiral Hatchet hands you an envelope sealed with the mark of the Horde.>\n\nThis is your commendation letter. It's the least I could do for you given the circumstances.\n\nReturn to Lady Sylvanas Windrunner with the letter and inform her of our status. Let her know that we will be ready to march on her command.\n\nGoodbye, {name}. You are an excellent soldier.\n\nNortheast, <lad/ma'am>. To Forsaken High Command!", progress = "And the orcs?", completion = "<Sylvanas raises an eyebrow.>\n\nSo the orcs are in order?\n\n<Sylvanas reads the commendation letter.>\n\nRecovered their supplies? Killed a dozen worgen? Toppled an ettin? Freed their soldiers and destroyed the Skitterweb matriarch?\n\nI say this rarely, {name}, but I am impressed. Perhaps your ability matches your aspirations. We shall see, for now you will be tested!", objectives = "Deliver the Admiral's Commendation Letter to Lady Sylvanas Windrunner at Forsaken High Command in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27097] = { id = 27097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Forsaken", description = "Fenris Isle stands defiantly at the heart of Lordamere Lake - a cruel memory of a time long since passed.\n\nThough no longer infested by gnoll vermin, a new threat has emerged.  Human refugees, driven from their holdings in Hillsbrad, have fled to Fenris Isle in hopes of escaping defeat at our hands. A critical error on their part.\n\nYou are to take Agatha with you to Fenris Isle and slaughter all humans. She will raise the fallen as Forsaken, bolstering our forces in the process.\n\nDo not fail me, {name}.", progress = "Victory!", completion = "I see everything, {name}. Through Agatha all is known to me.", objectives = "Raise 15 Forsaken by killing humans on Fenris Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27098] = { id = 27098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lordaeron", description = "Ride with me to the Sepulcher, {name}. There are many things I wish to discuss with you. It is imperative that you understand the history of Lordaeron and the plight of the Forsaken.", completion = "Do you now understand the importance of our mission here? Crowley and his Alliance dogs must be stopped!", objectives = "Accompany Lady Sylvanas Windrunner to the Sepulcher in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27099] = { id = 27099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Escape", description = "You must strike at their leaders, {name}. You will find them holed up in the old keep. Battle your way inside and find the holdouts! Turn them for your queen!\n\nNone shall escape the mighty grasp of the Forsaken!", completion = "It would seem that Crowley is more formidable than I anticipated. Still, he is a man - flesh and bone - full of secrets. Secrets that I know all about...\n\nYou have served me well, {name}. I could use someone of your ability at the Sepulcher. I have a plan to deal with Crowley and his insurgents once and for all. Will you help?", objectives = "Find the Refugee Leadership inside Fenris Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27100] = { id = 27100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Research", description = "The book you found appears to detail some form of research carried out by a member of the Twilight's Hammer.\n\nIt deals with the oozes in some way, but there are multiple pages missing.\n\nPerhaps if you found additional notes you might be able to make sense of it.", progress = "<You scroll through the notes, trying to put them in order.>", completion = "The notes deal with High Cultist Maziel's research on the elemental properties of quicksilver.\n\nHis obsession with the subject borders on the insane.", objectives = "Obtain 4 Twilight Research Notes from Mercurial Oozes in the Upper Silvermarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27101] = { id = 27101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maziel's Revelation", description = "The notes continue Maziel's rambling research into the properties of quicksilver and mercurial oozes.\n\nHe appears to have made a major discovery.  He mentions hiding his journal in the Lower Silvermarsh to the southwest.", completion = "Maziel's journal appears to be undamaged by the mercury.", objectives = "Find Maziel's Journal at the Lower Silvermarsh in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27102] = { id = 27102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maziel's Ascendancy", description = "Maziel's journal chronicles a ritual of ascendancy that would transfigure his body to one of pure quicksilver.\n\nThe ritual would take place in the cave near the Lower Silvermarsh, where Maziel would feed upon the mercurial oozes until achieving full strength.\n\nPerhaps it is not too late to put an end to his madness.", completion = "You've disposed of an enemy before he could grow more powerful.  By eliminating Maziel you've also ensured that his powers will not be used against the Earthen Ring.", objectives = "Slay Maziel inside the Silverlight Cave in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27103] = { id = 27103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shards of the Felvine", description = "The satyr Alzzin the Wildshaper has exerted his corrupt dominion over this part of Eldre'Thalas.  The Fruit of Fertility, now corrupted as the Felvine, should be close to Alzzin. It may be the key to purify this ancient place.\n\nWhen the great satyr falls, capture whatever essence of the Felvine you can.  Seal it in this Reliquary of Purity, and bring it to me.\n\nGood luck, and Cenarius' speed.", progress = "With the Sealed Reliquary of Purity in our possession, it will be possible not only to remove a corrupting threat from the world but also to study it under our judicious watch.  Perhaps we can even devise new means to combat the taint of corruption that ever threatens Azeroth.", completion = "You have done well, {class}, and for that I am forever in your debt.  Though the war is far from over, a great battle has been won against those who would bring about our doom.\n\nPlease - accept this gold as a token of my enduring gratitude.  If we ever cleanse Dire Maul, know that you will be welcomed here as a hero. Thank you.", objectives = "Use the Reliquary of Purity to capture a Felvine Shard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27104] = { id = 27104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alzzin the Wildshaper", description = "The monster responsible for the ruin you see before you is called Alzzin the Wildshaper. To reach him, however, you will need to also slay Zevrim Thornhoof, the satyr who currently holds the still noble ancient Old Ironbark in his grasp.\n\nOnce Ironbark is free, he will help you make an entrance into Alzzin's domain. Enter and slay him without mercy, for there is no other way.", progress = "Time is running short, {race}. I trust you will not fail.", completion = "Ah, very well done indeed. You've made an old spirit very happy this day. You deserve proper thanks for the risks you've taken.", objectives = "Kill Zevrim Thornhoof and Alzzin the Wildshaper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27105] = { id = 27105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unwelcome Guest", description = "You will find that Dire Maul is filled with many nature and arcane elementals. Somehow, a water elemental has found its way into this area. Please gather its essence and take it to me. I am curious as to how one of their kind got here, and what sort of agenda it may have against the natural elements of Eldre'Thalas.", progress = "Do you carry the essence, or did the task prove too difficult?", completion = "It is very troublesome that a water elemental was here, let alone one that powerful. Take this as my thanks for your efforts. I must examine this essence for any knowledge it may contain.", objectives = "Collect the Hydrospawn Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27106] = { id = 27106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Villain Unmasked", description = "<You find a complete list of all the Twilight's Hammer cultists in Stormwind.>\n\n<More importantly, you discover a letter from Major Samuelson to his compatriots outlining this entire scheme. The Prince was right: Samuelson is the real villain here, using his connections as commander of the city guard to disguise cult activity.>\n\n<It's time to return to Stormwind Keep and bring Samuelson to justice!>", progress = "You have evidence incriminating Samuelson? Let's see what he has to say for himself!", completion = "Samuelson - corrupted by the Twilight's Hammer? This must have been going on for years. Right here in my very keep!\n\nI am grateful that you and my son were able to get to the bottom of this before my city was brought to harm. I've underestimated how much Anduin has grown - his command of the holy light just saved my life, if not the entire kingdom.\n\nAs for you - words alone can't do justice to your heroism this day. Thank you, {class}.", objectives = "Unmask and slay Major Samuelson in the Stormwind Keep Throne Room.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27107] = { id = 27107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pusillin The Thief", description = "Me take quick nap earlier and stupid fast imp take book! Dagg'thol need book to follow orders and Master need book to conquer! Gah!\n\nYou {race} help me get book from imp, and I give you shiny something. Go, imp right there to da left! KILL!!!", progress = "{race} has book?", completion = "Now you watch Master use book to kill stupid trees and stupid goat men! YAR!", objectives = "Convince Pusillin to give up the Book of Incantations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27108] = { id = 27108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lethtendris's Web", description = "Blood Elf Lethtendris has web to catch magic here. She use for herself, but Master want to use for good of whole world! You help get web from stupid elf and not only will Dagg'thol reward you, you see how Master use it way better!", progress = "{name}, you have stupid elf's web?", completion = "This web have lots of magic! Master will be very happy now!\n\nAnd you make Dagg'thol happy, {race}. Take this so you believe how happy you make Dagg'thol!", objectives = "Obtain Lethtendris's Web.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27109] = { id = 27109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warped Defender", description = "The Ironbark and Warpwood were once the mighty protectors of Eldre'Thalas. Look at how they have fallen! Ultimately, their fate lies at the hands of myself and my fellow Highborne. We were reckless with our power, {race}.\n\nBut you, you can right the wrongs here! Venture forth and put Tendris Warpwood to rest. He was the mightiest and last defender of this area, and deserves spiritual release. Be wary, for if you do not dispose of the Ironbark Protectors prior to engaging Tendris, he will call them to assist.", completion = "Your work here was noble. Fret not, for Tendris' soul was crying to be put to rest. He is thankful.", objectives = "Kill Tendris Warpwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27110] = { id = 27110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Madness Within", description = "This madness must come to an end. The age of the immortals has long since passed. Destroy the guardians surrounding the five pylons to lower the force field. When this is done, destroy Immol'thar. With the Prince's power greatly reduced from the demon's demise, attack and end him as well. Lay the spirits of this city to rest, adventurer, and make the Prince pay for his wrongdoings.", progress = "Be wary, adventurer. The Prince is... persuasive.", completion = "We thank you, hero.", objectives = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\n\nEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\n\nReturn to the Shen'dralar Ancient in the courtyard should you complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27111] = { id = 27111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Treasure of the Shen'dralar", description = "In the library, Athenaeum, you will find an ancient chest hidden beneath the stairway. Take from it that which you desire.", completion = "You open the chest to find...", objectives = "Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27112] = { id = 27112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cursed Remains", description = "There are remaining beings here that pose a direct threat to us ever reclaiming this sacred city. Magister Kalendris and Illyana Ravenoak are both extremely dangerous and need to be disposed of as quickly as possible.\n\nExercise caution, for with there being so few remaining feeding off of Immol'thar's energies, they are likely to be stronger than they first appear.", completion = "Your dedication will make this all that much easier.", objectives = "Kill Magister Kalendris and Illyana Ravenoak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27113] = { id = 27113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shen'dralar Ancient", description = "Some beings here have miraculously managed to remain free of the darkness that runs so rampant. On the second story of the Court of the Highborne rests a Shen'dralar Ancient. Seek it out, it may hold a wealth of wisdom, perhaps even the secret to freeing Eldre'Thalas.", completion = "Our meeting is no coincidence, {name}.", objectives = "Speak to the Shen'dralar Ancient.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27114] = { id = 27114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordok Taste Test", objectives = "You da big boss now, so you get free sample of my better brews!  These drinks boost you up AND give you good buzz!  These are da good ones, chief... you try and tell Kreeg yourself!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27115] = { id = 27115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ando's Call", description = "You've done great work here, {name}. While you were out, that young Ando fellow was here looking for you. Said something about a metal bird.\n\nYou might want to go back to the shores of the Loch and see what he wanted.", completion = "It's working! My father brought it!", objectives = "Talk to Ando Blastenheimer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27116] = { id = 27116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Winds of Loch Modan", description = "Father finished the Skystrider. It's amazing! Once we get the bugs worked out, I'm going to use it to fight for justice, just like you.\n\nI know you've got to move on, and help other people, being a hero and all, but how about a ride? I'm about to take the Skystrider on its first flight, and I'll be honored if you join me. I'll drop you off at Algaz Station.\n\nWhat do you say?", completion = "What in blazes WAS that? A flying mechanostrider?\n\nYou know what, I don't want to know. I'm just going to pretend that didn't happen, and we'll be all nice and businesslike.", objectives = "Ride the Skystrider to Algaz Station and then speak with Mountaineer Stormpike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27117] = { id = 27117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brute Strength", description = "Gandling has brought his lieutenant, the Ravenian, with him.  This lumbering brute is far more dangerous than any of the other Scourge you will find upon the battlefield... even the abominations.\n\nYou will find the Ravenian within a tower near the southern end of town.  I recommend caution before fighting him, {name}.  He will not be a pushover.", completion = "Excellently done, {name}.", objectives = "Kill the Ravenian within Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27118] = { id = 27118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Broken Trap", objectives = "A large, broken trap lies before you.  From the looks of it, the ogres have tried to repair the trap but to no avail.\n\nA hastily written note lies next to the trap, and strangely enough it details exactly how to repair it: just a few simple adjustments ought to do it.  Were the trap repaired, an ogre passing near it might get trapped, and could be avoided.\n\nClearly, it would seem fortuitous that very few ogres know how to read.\n\nClearly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27119] = { id = 27119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordok Ogre Suit", description = "If you're going to fight the king of the Gordok then you're going to need to get by Captain Kromcrush. Now, you can get by him by killing him, sure. You might actually want to leave him alive.\n\nHow, you ask? I think I know! An ogre suit!\n\nI'll make you one if you bring me an Ogre Tannin from upstairs. I'm not going anywhere like this...", progress = "Just get me that Ogre Tannin, and I'll whip you up an ogre suit that will fool Captain Kromcrush into thinking you're one of his men.", completion = "Yeah, this will do the trick.  Just a slip here, and tuck here... heh - this is going to work out just fine!  <A broad smile beams from the chained goblin's face.>\n\nHere you go, you're all set.  Remember- this isn't the most securely fashioned item in the world.  You'll have ten minutes of use before it falls apart, and then you're not going to fool anybody!  Try using it just before you approach him to make sure it lasts as long as you're going to need it.", objectives = "Bring an Ogre Tannin to Knot Thimblejack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27120] = { id = 27120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordok Ogre Suit", progress = "Need another suit, do ya?  Well, I'm not going anywhere soon it seems - bring me another Ogre Tannin, and I'll make you another ogre suit.", completion = "Here ya go {name} - put this thing on, and you'll have ten minutes to do whatever.  Good luck!\n\nOh, and if you happen to find a key to get me out of here, BY ALL MEANS LET ME KNOW!!!" }
quests[27121] = { id = 27121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Knot!" }
quests[27122] = { id = 27122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fired Up and Not So Good To Go.", description = "Leave it to the Dark Irons to work with Ragnaros' toadies and worse. You can bet that insane Twilight's Hammer cult is behind the lot of this!\n\nTime to end their attacks on Ironforge once and for all. Oh, and tell Commander Cragfist what's happened here when we return; I'll need to work on getting the city and its good people back in order.", completion = "Dark Iron dwarves and Ragnaros the Firelord, ye say? At the behest of the Cult o' Twilight's Hammer?\n\nWell done! Ironforge is in yer debt.", objectives = "Slay Grand Ambassador Flamelash and inform Commander Cragfist in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27123] = { id = 27123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deepholm, Realm of Earth", description = "I knew you'd heed our call, {name}.  When Deathwing was first defeated by the other dragon aspects, he retreated to Deepholm, the realm of earth.\n\nDeathwing's return to our world left a rift open between Azeroth and Deepholm.\n\nIf we don't mend the breach, this land will be torn asunder.\n\nWe're doing our best to contain the damage on this side of the rift.  Aggra will take you through the rift so you can help repair the damage from the other side.\n\nGet on her wyvern when you're ready.", completion = "You've arrived just in time, {name}.  All our resources are tied up keeping the rift stable.\n\nWe need someone like you to help us recover the fragments of the World Pillar.", objectives = "Jump on Aggra's Wyvern and fly into the breach at the Maelstrom. Once you're on the other side, speak to Maruut Stonebinder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27124] = { id = 27124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Gordok Business", description = "Now you da king, so maybe you get prized Gordok artifact back from Guard Mol'dar!  Da king before you never listened, just like all da other kings since da old timey Gordok king!\n\nArtifact is called da Gauntlet of Gordok Might.  Old timey stories say only da one true king da Gordok can get it back.  You find it and it will become mighty gauntlet you wear forever!  Yar, I show you!", completion = "Wow... you ARE da true king! Old king never even ask about da gauntlet!\n\nLook - this mark on da gauntlet an old old OLD timey magic mark, older than da Gordok they say.  Well, I learn one thing as little ogre - how to make mark come to life and give power back to gauntlet!\n\nI do it for you, king!  Here, take da gauntlet and rule FOREVER!", objectives = "Speak to Guard Mol'dar in Dire Maul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27125] = { id = 27125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Gordok", description = "In Gordok society, their king is simply their strongest warrior. If anyone, ogre or otherwise, kills the current king, they are automatically hailed as the new one.\n\nThe new king receives tribute from any living guards, Stomper Kreeg, and Captain Kromcrush. Find and kill King Gordok while killing as few of their other leaders as possible, and not only will your reward be great, you will be able to use your power as king to halt the Gordok invasion without conflict!", progress = "I have faith that you will be able to complete the task set out before you.", completion = "Yes! I can see that you were indeed successful. You have received your tribute, the Gordok advance will exist no longer, and the Gordok are blissfully ignorant! This is a true winner's scenario, {name}.", objectives = "Kill King Gordok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27126] = { id = 27126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rush Delivery", description = "Peak Grindstone's team broke down somewhere out there to the west.\n\nThink you can make yourself useful for a change and rush some parts out to them, {race}?", progress = "Are those spare parts you have there?", completion = "I can't thank you enough, {class}. Now, let's see if we can get this catapult moving again.", objectives = "Deliver the Catapult Parts to Peak Grindstone on the Fractured Front in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27127] = { id = 27127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fired Up and Not So Good To Go.", description = "Dark Irons? Cho'gall?! We'll show them what becomes of those who attack Orgrimmar.\n\nLet us attack! We'll hurl their limbless corpses into the magma they so adore.\n\nYou'll tell Blood Guard Kang what's happened here when we're done, yes? Doubtless I'll need to spend time organizing the repair of the city...", completion = "Dark Iron dwarves and Ragnaros the Firelord, you say? At the behest of the Cult of Twilight's Hammer?\n\nWell done! Orgrimmar is in your debt.", objectives = "Slay Grand Ambassador Flamelash and inform Blood Guard Kang in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27128] = { id = 27128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Gordok", description = "You kill Gordok leader, you new ogre king. If you king, then ogre leaders like Kromcrush and Kreeg that survive pay you big tribute and you stop Gordok invasion. If you do that, then me very happy ogre and we take Dire Maul FOR DA HORDE!!!\n\nGo, little {race}! Kill ugly Gordok ogre king and maybe dis be new Stonemaul Hold! Yar!", progress = "You new Gordok king?", completion = "Little {race} did it! Now Horde more powerful than ever! YAR!", objectives = "Kill King Gordok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27129] = { id = 27129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Warpwood", description = "Just inside the eastern wing of Dire Maul one of the warpwood ancients, Furgus Warpwood, still lives uncorrupted. You must travel there and help him drive out the terrible creatures that have taken it as their own. Taking Dire Maul would be a major step in reclaiming Feralas for our people.\n\nYou can find Dire Maul to the southeast of here.", completion = "Have you been in contact with a druid of the talon recently, {class}? I can feel the lingering presence of one.", objectives = "Speak to Furgus Warpwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27130] = { id = 27130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Warpwood", description = "Just inside the eastern wing of Dire Maul one of the warpwood ancients, Furgus Warpwood, still lives uncorrupted. You must travel there and help him drive out the terrible creatures that have taken it as their own before they set their sights on Camp Mojache. Perhaps we can even enlist his aid afterward to ensure we maintain our presence in Feralas with enemies on so many sides.", completion = "Your face shows signs of desperate conflict. I honor your presence, brave {class}.", objectives = "Speak to Furgus Warpwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27131] = { id = 27131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highborne", description = "Estulan, a powerful and uncorrupt Highborne, has managed to enter the western wing of Dire Maul and has asked for assistance in cleansing it. Regardless of your personal convictions of the Highborne, it is an effort I must support for the good of Feralas. May the wind carry your spirit there with great swiftness.\n\nYou will find Dire Maul to the southeast.", completion = "I sensed your coming all the way from Dreamer's Rest. Your assistance would be most welcome.", objectives = "Speak to Estulan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27132] = { id = 27132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highborne", description = "Estulan, a powerful and uncorrupt Highborne, has managed to enter the western wing of Dire Maul and has asked for assistance in cleansing it. Regardless of your personal convictions of his kind, it is an effort I must support for our own good. Please hurry, we need every foothold in Feralas that we can get.\n\nYou will find Dire Maul to the west.", completion = "I sensed your coming all the way from Camp Mojache. Your assistance would be most welcome.", objectives = "Speak to Estulan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27133] = { id = 27133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes in the Sky", description = "The most dire, and most organized, threat to us in Feralas are the Gordok ogres in the northern wing of Dire Maul. I requested a druid of the talon to go there and scout it out. If he still lives, speak with him and he will act as your commander to stop the Gordok before they decide to attack.\n\nThat's an order, {class}.", completion = "Speak softly, {name}. The Gordok may not be intelligent, but they are still dangerous warriors.", objectives = "Speak to the Druid of the Talon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27134] = { id = 27134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre in the Field", description = "The most dire, and most organized, threat to us in Feralas are the Gordok ogres in the northern wing of Dire Maul. If we eradicate them and take Dire Maul for the Horde, we will possess a heavily fortified seat of power in this region with numerous artifacts to sweeten the deal. I sent in a small army of Stonemaul Ogres inside earlier - if any have survived, speak with them and finish the job.\n\nThat's an order, {class}.", completion = "These ogres no pushovers. I need you help me finish Orhan's task, {race}.", objectives = "Speak to the Stonemaul Ogre.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27135] = { id = 27135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something that Burns", description = "Alright, we need something that's going to make the compound go, \"Boom\"!\n\nI'm all out of gun powder, but I think I know what we can use instead... the heart of my fire elemental!\n\nHere, take my fire totem east to the Blood Trail. Just flip the switch on it near any of the lava pools over there and Magmatooth should be summoned. Bring back his heart and we'll be in business.", progress = "You have the heart yet?", completion = "Uh oh. Sounds like he wasn't very happy about the situation. How was I to know? I'm just an initiate after all.\n\nAnyway, I'll worry about Magmatooth later.", objectives = "Obtain the Burning Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27136] = { id = 27136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Energy", description = "It's taking every ounce of our power to keep this realm stable in the absence of the World Pillar.\n\nAs shaman we can tap directly into the energies of the elementals that inhabit Deepholm and use them to heal the damage that the rift is causing.\n\nTake this totem and place it on the ground outside.  Any energized geodes or lodestone elementals destroyed in its proximity will fill it with the energy we require.", completion = "Thank you, {name}.  We need all the power we can muster to keep Deepholm stable.", objectives = "Destroy 8 Energized Geodes or Lodestone Elementals near the Depleted Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27137] = { id = 27137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earth Girls Aren't So Easy", objectives = "Ol' Theradras was behind all the movin' amd shakin', ye say?\n\nAnd the Cult o' Twilight's Hammer put her up to it?\n\nWell done! Ironforge is in yer debt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27138] = { id = 27138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earth Girls Aren't So Easy", objectives = "Theradras wreaking havoc for the Cult of Twilight's Hammer, eh? And she's in pieces, now?\n\nWell done! Orgrimmar is in your debt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27139] = { id = 27139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hobart Needs You", description = "Heya, boss, Hobart Grapplehammer's wants to speak with you. He says it's a matter of some urgency.", completion = "There you are, my boy. I have something very important for you to do!", objectives = "Speak with Hobart Grapplehammer at the Town-In-A-Box on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27140] = { id = 27140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alexi's Gambit", description = "I require your assistance, {class}. Find the undead mage Vectus and the warrior Marduk deep within here. They run the scourge's plagued dragon operation and must be destroyed.\n\nPlace this Gambit in the viewing room where they are located. Hopefully, it will react with their forces and utterly destroy them!\n\nOh, defeating Vectus and Marduk afterward shouldn't be a problem.  Right?", completion = "You did it!  They are defeated!  And the Gambit... did it work?\n\nVery interesting. You've done well, {name}.", objectives = "Place the Gambit in the Viewing Room and slay Vectus and Marduk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27141] = { id = 27141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exploding Through", description = "What a find!\n\nRight here... exactly where my notes predicted it would be.\n\nWith any luck, inside this chamber will lie clues to the location of the legendary Coffer of the Promise.\n\nThat's right, {name}. It's not just a myth. I believe it truly exists.\n\nI'll explain more later. For now, just give me a hand with these explosives.", completion = "Shake it off, kid.\n\nHappens to me all the time...", objectives = "Assist Harrison Jones at the Khartut's Tomb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27142] = { id = 27142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lich, Ras Frostwhisper", description = "One of Kel'Thuzad's most trusted students oversees the operations in Scholomance. You must confront the lich, Ras Frostwhisper, in his lair. The door to his chamber is adjacent to the viewing room.\n\nDestroy him, {name}. Leave no trace of his existence so that he may never again bring such horrors into our world.", completion = "Ten thousand souls cry out in unison, {name}! You have struck a mortal blow to the Scourge and their masters.", objectives = "Destroy Ras Frostwhisper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27143] = { id = 27143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barov Family Fortune", description = "Within Scholomance lays the Barov family fortune. Alexi and I are the last two Barovs in existence.\n\nHowever, I am the only living Barov, so our family's vast empire belongs to me! Find me the deeds to Caer Darrow, Brill, Tarren Mill, and Southshore and I will repay you generously. The Barov estate will be reborn at long last!", progress = "Bow your head in my presence, {race}. I am a noble, after all, and you are a copperless peasant.", completion = "Excellent work, {race}. Alexi deserves nothing for his foolishness.", objectives = "Recover The Deed to Caer Darrow, The Deed to Brill, The Deed to Tarren Mill, and The Deed to Southshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27144] = { id = 27144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reckoning", description = "Your performance was admirable, soldier.  You make the Forsaken proud, which is more than I can say for our general, Koltira Deathweaver.\n\nI intend to have a word with that death knight.  He has shamed himself and his cause.", progress = "Yes?", completion = "I have nothing against the Knights of the Ebon Blade, but Koltira needs to be reminded who he works for now.  His loyalty must lie with the Horde.\n\nOr, more specifically, the Forsaken.\n\nI wouldn't plan on seeing Koltira anytime soon.  Now that I have him... you can rest assured that any bonds he may have had with that Alliance scum will be thoroughly broken.", objectives = "Stand by as Lady Sylvanas Windrunner speaks with Koltira Deathweaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27145] = { id = 27145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plagued Hatchlings...For Now", description = "One of the 'projects' underway here is the plagued dragonflight. Thankfully, they're only hatchlings right now, but if we wait much longer they will become one of the scourge's most powerful weapons and a major threat to all of Azeroth, especially my family's land!\n\nSlay ten of their whelps and be sure to take care of Rattlegore as well. He is in the small space beneath where the whelps are housed and prepares supplements to catalyze their growth. Hurry...before they get any bigger!", completion = "Well done, {name}!  It'll be a long time before they can grow another clutch of dragons.\n\n...At least, I hope it will!", objectives = "Kill 10 Plagued Hatchlings and Rattlegore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27146] = { id = 27146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doctor Theolen Krastinov, the Butcher", description = "Doctor Theolen Krastinov is responsible for the deaths of thousands. His nickname, The Butcher, is well earned for the atrocities he takes joy in executing. He must be punished, justice must be meted out.\n\nFind him and exact upon him the agony he has inflicted upon countless innocents, including me and my husband. Once he is destroyed, burn our remains. Turn them to ashes, {name}. Release our grieving souls.", completion = "I can feel my spirit healing, {name}. You have done my husband and I a great service.", objectives = "Destroy Doctor Theolen Krastinov, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27147] = { id = 27147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kirtonos the Herald", description = "With blood, Kirtonos may be summoned. It is with blood, then, that Kirtonos must be destroyed.\n\nWithin the Chamber of Summoning, you will find a brazier, upon which you shall place a drop of your own blood. Kirtonos will come - he cannot resist. When he appears, unleash the fury and wrath of a thousand innocent deaths upon him.\n\nShould you succeed, you will earn more than just our gratitude.", completion = "With the death of Kirtonos, a chapter in the horrible tale of Scholomance comes to a close. You have my deepest, everlasting gratitude for your bravery.", objectives = "Destroy Kirtonos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27148] = { id = 27148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "School's Out Forever", description = "Darkmaster Gandling serves as headmaster of Scholomance, and is therefore responsible for countless deaths at the hands of his students. For that he must be punished.\n\nHe will not come out easily. Lure him out by slaying his six professors whose rooms connect to the Headmaster's Study. Be wary, for when the last falls he will come, and he will come infuriated with vast magic backing his assault. Don't let him make it out of here alive.", completion = "Without a headmaster, the school will descend into chaos. It will not put forth any more of its vile 'students' into the field. Thank you.", objectives = "Kill Darkmaster Gandling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27149] = { id = 27149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "School of the Damned", description = "Greetings! As you can see, the Western Plaguelands is very nearly free of the last remnants of the scourge. However, their school of necromancy, Scholomance, still sits full of lost young souls training to become scourge sorcerers! Our work here will be for naught if we do not stop this flow of fresh, not to mention very powerful, necromancers.\n\nTravel southeast to Scholomance and find Weldon Barov. He is the last living member of the Barov line that once owned all these lands and is our current contact.", sourceObjective = "Speak to Walden Barov in Scholomance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27150] = { id = 27150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Menders' Stead", description = "It's likely that the battle for Andorhal will start up again soon.  In the meantime, you could probably stand to practice your skills as a {class}.\n\nEast of here is a large farm that has been taken over by the Argent Dawn and the Cenarion Circle.  I don't doubt that they'll have some work for you.", sourceObjective = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.It's likely that the battle for Andorhal will start up again soon. In the meantime, you could probably stand to practice your skills as a {class}.\n\nEast of here is a large farm that has been taken over by the Argent Dawn and the Cenarion Circle. I don't doubt that they'll have some work for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27151] = { id = 27151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taelan Fordring's Legacy", description = "Greetings.  How do you do?  My name is Daria.\n\nI am one of the priests in charge of preserving the peace here in Hearthglen.  One of my duties involves maintaining the tower down the trail to the southeast of Hearthglen.  This particular tower is of personal importance to the Highlord.  It's the place where his son was killed.\n\nWith the recent incursion of gnolls, however, maintenance of the tower has grown difficult.  Will you help me rid the trail of some of these gnoll vandals, so I can do my duty?", completion = "I must admit, {name}... I have been using my mind vision spell to keep tabs on you.  And I must say... the number of gnolls you found on the trail is truly staggering!", objectives = "Kill 10 Redpine Looters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27152] = { id = 27152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unusual Behavior... Even For Gnolls", description = "Allow me to concentrate for a moment.\n\n<You feel Daria's mind vision travel elsewhere, then it returns to you.>\n\nFurther down the trail, south of Taelan's Tower, the gnolls have carved out a small meeting area to the east of the main road.  Something is happening there... I'm not certain what.  We should investigate.  I will look for anything out of the ordinary... you just protect yourself.", completion = "Gnolls and necromancy... what a surprise!  And I thought that, here in the Western Plaguelands, we had put these dark days behind us.\n\n<You sense Daria's eyes focusing on something on the ground.>\n\nWait... what is THAT?", objectives = "Investigate the gnoll hideout along the trail to Hearthglen in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27153] = { id = 27153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Good People of Hearthglen", description = "See those reagents over there?  And these supplies right here?  Those belong to the Argent Crusade.\n\nGnolls are known for thievery, but as far as I know, Hearthglen hasn't had any incursions since the Redpine came.  Very suspicious.\n\nI know a few helpful folks within Hearthglen: Morris Vant, Outfitter Mendelev, Bree Ironstock, and High Cleric Alphus.  All can be trusted, and are well-connected.  Question them, to find out if they know anything about these lost supplies.", completion = "Did you notice, {name}?  Many names were mentioned, but one name was mentioned far more than the others.\n\nBisp.", objectives = "Speak with Morris Vant, Outfitter Mendelev, Bree Ironstock, and High Cleric Alphus within Hearthglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27154] = { id = 27154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bagging Bisp", description = "Magus Bisp is one of Hearthglen's most preeminent arcanists.  To imagine that he would be interacting with gnolls... and dabbling in necromancy?  Unthinkable.\n\nYou'll find him atop the tower near Hearthglen's main gate.  Hopefully he'll have an explanation for all of this.  If not, well... I wouldn't go to the top of that tower unprepared, {name}.", completion = "I suppose that we can take his aggression as an admission of guilt.  You alright, {name}?", objectives = "Speak with Magus Bisp atop the mage tower in Hearthglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27155] = { id = 27155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning Yourself In", description = "So... you killed a member of the Argent Crusade, inside of Hearthglen.  Usually that's not smiled upon, even in self-defense.\n\nI recommend you come back to Mardenholde Keep, and turn yourself in to Highlord Fordring.  Hopefully he will hear you out, and will be sympathetic with your situation.  I hope I haven't gotten you in any trouble.", completion = "I'm already aware of your actions, {name}.  I welcome you into my town, give you my blessing, and what do you do?\n\nYou slay the traitor that we've been hunting down for weeks.  Well done.  Your heroism is budding much earlier than even I had anticipated.", objectives = "Report to Highlord Tirion Fordring at Hearthglen in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27156] = { id = 27156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's About Time!", description = "Finally!  You're here!  Get to work!\n\nMy men have been sparring with these wooden practice dummies for far too long.  Sure, you can learn how to swing a sword by practicing with a dummy, but real combat requires a real combatant.\n\nHmmm... I had asked for them to send me someone imposing, but I suppose a skinny-armed {race} {class} will have to do.\n\nNow get in there and teach my men how to fight!", progress = "I'm not paying you to talk to me.  I'm paying you to talk with my soldiers... and then fight with them.", completion = "I'm just looking over my paperwork here, and it says that we were expecting a FEMALE {race} {class}.  You're not, umm...\n\n\n\nNever mind.  It would appear that you are not the person that I originally hired, but you did a good job.  So I'm going to pay you anyhow.", objectives = "Challenge and defeat 7 Hearthglen Trainees.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27157] = { id = 27157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drudges... <Sigh>", description = "Say, I never caught your name.  {name}?  Pleased to meet you, {name}.\n\nI've got one more problem that needs fixing, and you have a look about you that just screams \"I'm a problem-fixer\".\n\nThere's a small mine on the northern edge of Hearthglen, where we get most of the ore that the town needs.  My drudges who work the mine normally do a decent job.\n\nUnfortunately, it seems that a larger-than-average spider has taken up residence within this cave.  Think you can clear things up for me?", completion = "Nice work!  In retrospect, I'm glad that other {race} {class} never showed up... you've proven to be all the help I need.", objectives = "Kill Shadril within the mine inside Hearthglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27158] = { id = 27158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "Hurry, {name}... there isn't time to waste.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  King Wrynn has rolled the dice and sent a death knight to lead the charge for his cause, but I'm sure he can use all the help he can get.  With Arthas dead, now is the time for the Alliance to start to retake Lordaeron.\n\nSpeak with the gryphon master, Bibilfaz Featherwhistle, when you are ready, and he will put you on the first flight out there.", completion = "It's about time you arrived, {class}.", objectives = "Report to Thassarian within Andorhal in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27159] = { id = 27159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge First... Horde Later", description = "Darkmaster Gandling of the Cult of the Damned leads the Scourge offensive here in Andorhal.  My old counterpart, Koltira, leads the Forsaken forces.  If we're to win Andorhal, we'll have to defeat both, but we will certainly fail if we take on both at once.\n\nI know Koltira well enough to know that he will focus on the Scourge first.  We will do the same.\n\nTake out the weaker, desiccated Scourge to reduce their numbers.  The Forsaken will have to wait to taste our wrath.", completion = "You may not act quickly, but at least you do not fail me.\n\nVery well.  I will have a more important task for you, {name}, when the time is right.", objectives = "Slay 15 Desiccated Scourge within Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27160] = { id = 27160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Machines", description = "Dried-up Scourge... weak.  Abominations... strong.\n\nWe defeat strong abominations... we win war.", completion = "Abominations... strong.\n\n{name}... stronger.", objectives = "Destroy 6 Opengut Behemoths in Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27161] = { id = 27161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Endless Flow", description = "Araj the Summoner is bolstering the Scourge defenses with simple skeletons... an army of weaklings that will overwhelm you before it overpowers you.  He has assembled animi within Andorhal's northern towers that spew these skeletons out at an alarming rate.  But I've got the solution!\n\n<Lang passes you a handful of grenades.>\n\nTheir function is simple.  Throwing these grenades at a bone animus... or, for that matter, a mob of skeletons... will reduce them to splinters.", progress = "I know what those devices sound like when they've blown up... and I haven't heard that sound yet.  Get back out there, {name}.", completion = "These grenades are all explosives, nothing more.  I may not be a goblin engineer... but I still understand the value of being able to just explode things every once in a while.", objectives = "Use Lang's Hand Grenades to kill 5 Stickbone Berserkers and to destroy a Scourge Bone Animus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27162] = { id = 27162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholomancer", description = "The Scholomance is one of the few Scourge holdouts remaining west of the Thondroril.  The headmaster of Scholomance, a cultist by the name of Darkmaster Gandling, has made an appearance on the battlefield.\n\nThis will be his final mistake.\n\nYou will find Gandling in a square near the southern end of town.  I want you to fight and weaken Gandling.  I will join you to help finish him off.", completion = "Excellently done, {name}.  And now, with the leader of the Scourge forces eliminated from Andorhal, we bide our time.", objectives = "Kill Darkmaster Gandling within Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27163] = { id = 27163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brute Strength", description = "Gandling has brought his lieutenant, Rattlegore, with him.  This clattering horror is far more dangerous than any of the other Scourge you will find upon the battlefield... even the abominations.\n\nYou will find Rattlegore within an old town-hall building, near the center of town.  I recommend caution before fighting him, {name}.  He will not be a pushover.", completion = "Excellently done, {name}.", objectives = "Kill Rattlegore within Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27164] = { id = 27164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Araj the Summoner", description = "With the animus destroyed, the next logical step is to take out Araj himself, and to take a shard of his phylactery.  You've probably already seen him, lurking at the fountain in the center of town.\n\nTake my grenades with you.  They won't do anything to Araj, but if he decides to summon any of those skeletons, you can use them to blow them away.  Again.", progress = "Araj is a formidable opponent.  Be prepared.", completion = "Araj dead... this is good.  That gnome has done his part in winning this war.  As have you, {name}.", objectives = "Kill Araj the Summoner. You may use Lang's Hand Grenades to destroy Stickbone Berserkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27165] = { id = 27165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory, For Now", description = "The Alliance are victorious, and our forces are still strong.  Military strategy dictates that we attack the Forsaken now, while they are recovering and unaware.  I made a deal, however...\n\nWe will wait.  We attack Koltira and his troops when the time is right.  In the meantime, speak with Ginny Goodwin and take a flight to the Chillwind Camp, to our south.  Commander Ashlam Valorfist will give you your next assignment.\n\nYou will hear from me when you are needed again in Andorhal.", completion = "Word arrived shortly before you did, {name}.  With the Scourge ejected from Andorhal, we are one step closer to retaking Lordaeron.", objectives = "Report to Commander Ashlam Valorfist at Chillwind Camp in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27166] = { id = 27166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Fletch!", description = "We must always be prepared for battle, {name}.  Whether that battle is against the Forsaken in Andorhal, against the Scourge in the east, or against some yet-unknown foe is unknown.  What is known, is that we must be ready.\n\nWe are low on arrows.  I can obtain the shafts and heads, but I still need feathers.  The birds that circle to the northwest typically molt this time of year.  Would you mind traveling out into the field and gathering some of these feathers for our camp?", progress = "It's good to see you back, {name}.", completion = "I will have my fletchers get to work on these.\n\nI'm glad to see you being so useful right away, {name}.  Perhaps later I will have some more exciting tasks for you.", objectives = "Obtain 9 Brownfeather Quills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27167] = { id = 27167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mighty Hunger", description = "I hail from Westfall, far to the south... as do these men that travel with me.  We are farmers, and nothing more.\n\nI had been told that Lordaeron had been healed, and that it was ready for tilling.  However, this \"Commander\" now tells me that it's too dangerous to proceed.  He says that there's a war going on, and that the plaguelands still aren't healed.\n\nBefore anything else, I need to get some food in my men's stomachs.  Anything will do.  Bear seems to be plentiful.", progress = "We've traveled a long way.  Anything you can spare would be appreciated.", completion = "You hunt like a true {class}.  Even if we can't set up our homesteads... at least we can still eat.", objectives = "Obtain 5 Sides of Bear Meat from Shaggy Black Bears in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27168] = { id = 27168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those That Couldn't Let Go", description = "Sorrow Hill, up the road to the northeast, was one of the first places that the Argent Crusaders and Cenarion Circle were able to heal.  The area is now freed of the Scourge.\n\nHowever, there are still many specters of the past that, for some reason, have not passed on into the next world.  They may be mourning, they may have unfinished business... or they may just be lost.\n\nTake my thurible and use it to douse them with holy incense.  One way or another, we will help them move onto the next plane.", completion = "Hopefully most of them passed on peacefully.  I thank you, {name}.", objectives = "Use the Holy Thurible on 12 Withdrawn Spirits in Sorrow Hill, and slay them if they react negatively.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27169] = { id = 27169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uther's Blessing", description = "These farmers from the south wish to take these farms, but I can't let them enter the plaguelands unprepared.  Even with the Scourge gone, danger still looms in the form of the Forsaken.  No, we must be ready to fight... and that includes our new visitors.\n\nBefore doing anything else, however, I would recommend that you travel to Uther's Tomb, to the east, and place this tribute before his statue to ask for his blessing.  Speak with the priest that tends to the tomb when you are finished.", progress = "Uther was a great hero.  It is my honor to serve him, even after he has passed.", completion = "You and the humans at Chillwind Camp wish to re-take Andorhal?  I wish you luck.", objectives = "Enter Uther's Tomb, and use the Chillwind Tribute before his statue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27170] = { id = 27170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abandoned Crypt", description = "If you truly intend to move forward in this battle for Andorhal... well, perhaps I can help.\n\nTo the east lies a large crypt.  The bottom level of the crypt was once used for storage of weapons and armor... until the Scourge came.  Now that the undead have left, the weapons are free for the taking.\n\nMost of the weapons are probably rusted and rotten by now, but they will serve better than tunics and pitchforks.", completion = "Scattered all over the bottom level of the crypt, you find shattered crates that once held weapons and armor.\n\nIt appears that somebody got here before you did.", objectives = "Find the Weapons Crate at the bottom of the Crypt in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27171] = { id = 27171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambushed!", description = "As you turn around, you see the silhouettes of shambling skeletons on the stairs.\n\nThe undead aren't gone from this crypt.  They were lying in wait!  Furthermore, they appear to be armed with the weapons that you came looking for.\n\nYou'll have to escape from the crypt.  On your way out, you should gather as many pieces of equipment as you can.", progress = "What happened at Uther's Tomb, {name}?", completion = "Attacked by ghosts?  Strange.  I suppose that crypt wasn't fully healed after all.\n\nYou just missed Thurman Grant... you remember, that oaf of a farmer that was here earlier.  He took his men with him and traveled to the nearest farm... against my orders.", objectives = "Obtain 4 Time-Worn Breastplates and 4 Rusted Swords.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27172] = { id = 27172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Writhing Haunt", description = "The farmers traveled to the Writhing Haunt, an old farm to the northeast, across the river.  Someone needs to keep an eye on them.\n\nBring them those rusty weapons and armor you found.  We can't have them fighting with pitchforks.", progress = "Did Valorfist send you?  He doesn't know when to let up, does he?", completion = "Well, now that you're here, we'll gladly take that armor off your hands.\n\nYou can keep the weapons, though.  These men wouldn't know which end to hold.", objectives = "Bring the Battered Weapons and Armor to Thurman Grant at the Writhing Haunt in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27173] = { id = 27173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Is Our Army", description = "I told Commander Valorfist that we could hold our own, and we intend to.  I had a little conversation with the death knight general, Thassarian, on my way over here.  We farmers plan to help in our own way.\n\nWe will take control of this farm, begin to cultivate the land... and then when the battle for Andorhal commences, we will attack the Forsaken from the rear.  They'll never expect it.\n\nFirst, we need to get rid of these Forsaken outriders.  Kill some, then return to me.", progress = "My men need your help, {name}.", completion = "You fight well, {race}.  My men could stand to learn a few moves from an experienced {class} like you.", objectives = "Kill 10 Forsaken Outriders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27174] = { id = 27174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Training", description = "In fact, you might still be able to help train some of my men.  You probably noticed the abomination outside.  We initially tried to fight him, but he didn't fight back.  He seems to want to help out on the farm.\n\nTake a group of four settlers and challenge this abomination to combat.  He seems to be pretty tough, but with one of him and five of you, I think you'll have a chance at beating him.", progress = "If we're going to help out in this battle for Andorhal, we need to learn how to fight.", completion = "We can handle things from here.  I thank you for your help, {name}.\n\nI assume that when we next meet, it will be in battle.  Take care of yourself until then.  We'll need all the help we can get.", objectives = "Speak with Gory at the Writhing Haunt and challenge him to combat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27175] = { id = 27175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Menders' Stead", description = "These men and women here at Chillwind Camp have noble goals, but their ultimate purpose is war.  I would like to offer you an opportunity to pursue more peaceful goals.\n\nAt the Menders' Stead, beyond war-torn Andorhal to the north, the Argent Crusade has joined forces with the Cenarion Circle.  Together, we work on healing this land from the plague that used to reign here.\n\nAre you interested in joining our cause, {class}?", completion = "Welcome, {class}.  As you can see, our camp is a joint expedition between Argent Crusade members and Cenarion Circle druids, but we welcome all who wish to help heal the land.", objectives = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27176] = { id = 27176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Disc", description = "The etching around the surface of this object indicates that it is of ancient origins, and yet no signs of wear can be detected.\n\nA hole on its edge, full of splintered wood, indicates that it is meant to be put atop a wooden staff of some sort.\n\nBefore showing this to Doctor Jones, you should find the other piece.", progress = "Yes, {name}?", completion = "<Doctor Jones puts on his spectacles.>\n\nLet's have a look at this. Shall we?", objectives = "Obtain the Sultan's Staff, then use the Elaborate Disc to create the Shaft of the Stars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27177] = { id = 27177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvage Operation", description = "Between the Horde and the naga, our fleet has been decimated. We can't do anything to bring back the men who gave their lives to the sea, but sink me if I allow all of our supplies to be lost forever.\n\nSwim out to the Obsidian Breakers southwest of Highbank and retrieve our supplies from the wrecks and the ocean floor.", progress = "How much were you able to recover?", completion = "Look at all this! You were able to recover more than I thought. We can outfit a whole squad of marines with this stuff.\n\nWe have the gear. If we only had some way to bolster our numbers here in the Highlands...", objectives = "Retrieve 8 Recovered Supplies from Waterlogged Crates in the Obsidian Breakers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27178] = { id = 27178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga Reinforcements", description = "They've come slithering up from the ocean depths, {name}. The naga. I think their intent is to reinforce the Bastion of Twilight, probably by heading inland via the Verrall river. We can't let that happen!\n\nTeach them that these shores are ours now, and send them scurrying back to the lightless depths.\n\nKill the Blackscale naga worming their way through the Obsidian Breakers!", completion = "That'll send 'em packing, {name}! Cho'gall won't be able to count on the naga to back him up in this fight. From here on out, it's just us versus the Twilight's Hammer.\n\n\n\n...And the Horde.", objectives = "Slay 10 Blackscale Myrmidons or Blackscale Seacallers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27179] = { id = 27179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Work", description = "This unfortunate pygmy was in the wrong place at the wrong time.\n\nAs you ponder his bad luck, you take notice of the symbols covering his shield - far too elaborate for pygmy scrawl.\n\nConfident that Doctor Jones will find such objects of interest, you set out to find more fragments like this one.", progress = "What'dya have there, friend?", completion = "These tablets are covered with titan writings. There's never-before seen information here, {name}!\n\nMissing pieces to an ancient puzzle...\n\nGood work!", objectives = "Collect 10 Ancient Tablet Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27180] = { id = 27180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Dead", description = "A convoy of veteran troopers and Forsaken catapults were ambushed earlier today while attempting to cross Olsen's Farthing, directly south of here. It was a total loss: all troopers were killed and all catapults destroyed.\n\nBloodfang's pack was responsible for the ambush, though likely they have all fled back into the hills, preparing their next cowardly strike. Their day will come, but for now I want you to go to Olsen's Farthing and honor our fallen.\n\nRecover their Forsaken insignias.", progress = "Have you recovered the insignias?", completion = "I will see to it that these insignias are returned to the Undercity at once. The registrar will place their names in our records so that their sacrifice may never be forgotten.", objectives = "Recover 6 Forsaken Insignias from Veteran Forsaken Trooper corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27181] = { id = 27181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excising the Taint", description = "It looks like a group of the ambushers stayed behind. Make them pay for their insolence! Kill all of the Bloodfang stalkers at Olsen's Farthing. For Sylvanas! For the Horde!", progress = "You found the ambushers?", completion = "<The Banshee Queen's voice invades your thoughts.>\n\nYou have avenged the fallen, {name}, but there is more to be done.", objectives = "Kill 10 Bloodfang Stalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27182] = { id = 27182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit of Witch Hill", description = "The marsh seems to have a strange effect on humans. Some grow mad simply by living here.\n\nAnyone who has ever settled at Swamplight Manor has gone mad in a spectacular way. The latest owner, one \"Swamp Eye\" Jarl, is already showing signs.\n\nI don't completely understand what's happening there, you'd have my thanks for looking into it.\n\nThe manor is at the eastern edge of the swamp. Trek east across Bluefen and past North Point Tower. The manor is in a haunted patch of land called Witch Hill.", completion = "Have you come here to spy on me? No?\n\nPerhaps you have an appreciation for fine cuisine, then? Good, you can help!", objectives = "Speak with \"Swamp Eye\" Jarl at Swamplight Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27183] = { id = 27183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsh Frog Legs", description = "I like cooking.  Good swamp cooking.  Fried green frog legs and the like.\n\nAnd I'm all out of legs. The manor is overrun with frogs, though. Giant marsh frogs. Think you could bring me some of those legs? Nothin' to it, really. Just bop 'em on the head and bring me the legs.\n\nThen I'll make a stew and stew it up and suck it down and give you some too.\n\nDo you like stew?", progress = "Spice.  We could all use some spice in our life.  You agree?", completion = "Ah, that's the spice!  Now here's some swampy good stew.", objectives = "Collect 10 Marsh Frog Legs from Giant Marsh Frogs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27184] = { id = 27184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl Needs Eyes", description = "Eye juice is good juice for drinking.  Too bad most critters only have two eyes.\n\nBut spiders have lots of eyes.  Lots and lots.  And Darkmist eye juice is tasty.  Smooth and salty!  Unpopped spider eyes... I taste them already.\n\nDarkmist spiders are west of here, in the Darkmist Cavern.  You figure the spiders are named after the cave... or is it the other way around?", progress = "Where are those eyes?", completion = "You got the eyes!  You got the eyes!  Tasty, tasty spider eyes!\n\nSome eyes... when you stare at them they stare back. Eat those last.  They keep you company... out in the swamp.\n\nHello, little spider eyes.  Hello!  You taste like chicken.  Gooey, salty chicken!\n\nMmmh.", objectives = "Collect 20 Unpopped Darkmist Eyes from Darkmist spiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27185] = { id = 27185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting the Competition", description = "Look, I'm not about t' play games with ye. The Scarlet Crusade's Crimson Hammersmith was nothin' worth mentionin' before, but now that they're Balnazzar's Risen, the damned dreadlord has taught him t' make all sorts of powerful demonic weaponry.\n\nIt's simple. Find their blacksmithing plans and kill the Risen Hammersmith when he comes for 'em, so that we can make sure their army doesn't get their hands on demon armaments. They're powerful enough as it is!", progress = "Are we back on top of the arms race?", completion = "Nicely done, lad! Without them new weapons, they're just as easy t' kill as they were when they were alive!", objectives = "Kill the Risen Hammersmith.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27186] = { id = 27186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl Needs a Blade", description = "I have cutting to do.  I can't tell you what I'm going to cut, but... I need myself a blade.  A certain blade...\n\nSome people call it a sword.  I call it a swing blade.\n\nYou help me?  Those fish-men, you know, murlocs or whatever they're called.... There's one they call Razorspine, carries a big sword, lives north of here near the beach. That's the sword I need!\n\nBut don't sleep on this.  What I'm cutting won't keep forever...", progress = "You have my blade??", completion = "That's a good blade.  It has a good swing.  It's a good swing blade.  Thank you.  Thank you, thank you, thank you!!!  Now I want to try it....  \n\nLater.  I'll try it later.  But like I was saying... thanks.", objectives = "Obtain Razorspine's Sword.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27187] = { id = 27187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do the World a Favor", description = "Hyenas, on their best day, are a nuisance.\n\nThese foul specimens have a particularly nasty disposition, are riddled with all manner of disease, and are simply a blight on the face of dogdom.\n\nDo the world a favor and rid the deserts of Uldum of this mangy menace.", objectives = "Kill 12 Mangy Hyenas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27188] = { id = 27188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Haunting Witch Hill?", description = "I traveled out here to pay Jarl a visit at his new home and it's been a nonstop horror show ever since! There's something seriously wrong here and I can't be the only one who sees it...\n\nHave you seen the ghosts and corpses shambling about Witch Hill? I've a feeling that if anyone knows what happened here, it is them. Seek out these risen husks and risen spirits in the surrounding area, grant them rest through combat, and see what you can learn from them before this evil consumes Jarl!", progress = "What have you learned from the spirits haunting this place?", completion = "<Mordant produces a small sheet of paper and a pen, beginning to scribble down notes on your findings.>\n\nFrom your findings, the spirits in this place must amount to everyone who ever lived on this land, not just the previous occupants.\n\nSomething has been corrupting and killing them. Those who follow don't learn the truth until it's too late. We have to put an end to this, {name}!", objectives = "Gather information by defeating 10 Risen Husks or Risen Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27189] = { id = 27189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Witch's Bane", description = "In my years as an herbalist, I've often observed that nature will provide subtle cures to the most vexing of problems. I've read that hedge mages and witch doctors often use the smoke of an herb known as witchbane to draw evil from its hiding places.\n\nIf true, this would mean witchbane should be growing near the shallow waters of Witch Hill. You should be able to identify it by its broad leaves and reddish central stalk. Bring me any of the herb you can find, {name}. It may be our only hope.", progress = "Were you able to gather any of the herb? We must work quickly, before whatever evil is behind this infestation consolidates its hold on this area.", completion = "<Mordant accepts the bunch of herbs from you.>\n\nThese match the description exactly! I prepared the torch while you were out. All that remains is to fasten the herbs to the end here.", objectives = "Collect 9 sprigs of Witchbane near Witch Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27190] = { id = 27190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Witch Hill", description = "The torch is ready. Plant it at the end of the dock and be prepared to face whatever comes forth.\n\nI have no idea what the torch's smoke may reveal... if anything emerges at all. I must say, I have my doubts about this kind of folk magic, but we haven't time for anything else. For your sake and Jarl's, I wish you luck.", progress = "Is it over?", completion = "It worked?\n\n<Mordant clears his throat.>\n\nI mean... it worked! Jarl and I are in your debt, {name}. Now the only remaining problem is my friend's taste in furniture, and I'm afraid that won't be solved as easily.", objectives = "Plant the Witchbane Torch at the end of the dock and defeat the evil haunting Witch Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27191] = { id = 27191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry as an Ogre!", description = "You meet some people out here sometime. Nice people. Met an ogre once. Ogres get hungry just like me.\n\nI'll never forget what he said. He said \"Mud big ogre. Me hungry. Go bash fishy. Bring Mud food. You feed Mud or Mud eat you.\"\n\nSo I got him those fish and he ate 'em up. That's when I started too. The heads are the best part, all soggy-like.\n\nDon't crush those heads now. It makes them sad. Sad heads aren't good eating. Get me happy heads and I'll eat them and be happy too.", progress = "Jarl's hungry. Just like that ogre.", completion = "Wonder what it's like to be an ogre. Big people have to eat more.\n\nOgres must be even hungrier than me. That doesn't sound very fun.", objectives = "Collect 8 Mirefin Heads from Mirefin Murlocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27192] = { id = 27192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Ezra Grimm", description = "Men as far as Kul Tiras spoke of the legendary Ezra Grimm's premium tobacco. It was a delicacy enjoyed by every single person of importance that visited Stratholme. King Terenas, Uther the Lightbringer, Highlord Fordring...yes, they all enjoyed Grimm's specialty.\n\nSadly, Ezra stayed in his shop when Stratholme was invaded, swearing on his life that the Scourge would never touch his tobacco. Venture forth and see if even one bit remains here...it is worth its weight in gold, I assure you.", progress = "Did you find any?", completion = "Truly, you have uncovered the snuff of legends. It is nearly impossible to place a value on this historical tobacco.\n\nHere, have a few coins.", objectives = "Recover a box of Ezra Grimm's Premium Tobacco.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27193] = { id = 27193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek and Destroy", description = "<The Banshee Queen's voice invades your thoughts once more.>\n\nSearch the nearby farmhouses for Alliance stragglers. Keep an eye out for any information that could lead us to Crowley and Bloodfang. Seek and destroy all that would stand in your way, {name}!", progress = "What is your status?", completion = "<The Banshee Queen's words float in your head.>\n\nThis book documents a recent meeting with Ivus Bloodfang. The location mentioned is the Deep Elem Mine. I know of this place. It has only one entrance.\n\nWe shall corner and crush them!", objectives = "Search the Farmhouses at Olsen's Farthing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27194] = { id = 27194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cornered and Crushed!", description = "<The Banshee Queen speaks through your mind.>\n\nWe must act quickly, {name}. They mustn't be given the chance to flee. I am dispatching a squadron of my most powerful troopers to the Deep Elem Mine. I'm also sending the Horseman with them to ensure that nothing goes wrong. Meet him at the Deep Elem Mine, east of Olsen's Farthing, and CRUSH those rats.", completion = "I 'spose we're to corner them first then crush, eh?", objectives = "Report to Master Forteski at the Deep Elem Mine in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27195] = { id = 27195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nowhere to Run", description = "The mistress has put me in charge of this lot. Our primary mission is to get in there, corner the rats, and kill 'em all, including Bloodfang.\n\nYou've done us a solid service in gettin' the information, {name}. Join in the glory and help us drive a sword through their miserable skulls!\n\nLet me know when you're ready and I'll call for the charge.", completion = "WHAT!?\n\n<Sylvanas shrieks.>\n\nCROWLEY!!!!!\n\nBastards. Those were some of our strongest soldiers. I have underestimated Crowley and Bloodfang for the last time. Clearly they are an enemy the likes of which we have never seen - willing to sacrifice their own to set a trap like this... unheard of in Alliance warfare.", objectives = "Escort Master Forteski through the Deep Elem Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27196] = { id = 27196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On to Something", description = "This is remarkable work you've done! Especially for someone who hasn't taken my courses.\n\nThese tablets provide new information on several subjects.\n\nThey indicate that these obelisks are part of an enormous ancient mechanism that once kept this whole region masked from the rest of the world.\n\nThey also depict how to recharge the mechanism, which is where your Shaft of the Stars comes in...\n\nGet ready, {name}. We have some history to make!", progress = "Alright, now let's see what this staff can show us...", completion = "Would you get a load of this place!", objectives = "Accompany Harrison Jones to the Chamber of the Stars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27197] = { id = 27197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Resumes!", description = "Word is in from Andorhal, {name}.  The battle has resumed.\n\nIt has become somewhat well-known among the Alliance forces that you're a hero of the first battle of Andorhal.  Thassarian has requested your presence immediately.", completion = "Word has it that you helped those farmers arm themselves.  Well, now they've initiated the attack without my order!  They've forced my hand.\n\nThe battle has resumed.  This time, we fight the Forsaken... and I fight Koltira, my old brother of the Ebon Blade.", objectives = "Report to Thassarian at Andorhal in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27198] = { id = 27198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supporting the Troops", description = "I'm no military expert, but this battle looks to be in our favor.  Our defenders are equally matched with their deathguards, but the farmers' militia has taken them by surprise from the rear.  For the Alliance!\n\nStill, we should all do what we can to make sure that we win.  Travel east into Andorhal and slay the Forsaken deathguards that are fighting with our men.  The sooner they die, the quicker we can re-take Andorhal!", progress = "For the Alliance!", completion = "You fight well, {name}.  I wish I had your ability... and your bravery.", objectives = "Slay 15 Andorhal Deathguards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27199] = { id = 27199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes to Ashes", description = "To the east, deep within Forsaken-held Andorhal, you will find their commanders.  They do not fight, but call out orders from horseback.\n\nHunt down and slay these commanders, {name}.  The Forsaken won't stand a chance.", progress = "You will find them to the east, {name}.  Do not fail me.", completion = "Well done.  With them out of the way, I have no more excuses.\n\nSoon, I must battle Koltira, for honor and for Andorhal.", objectives = "Slay 3 Deathguard War-Captains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27200] = { id = 27200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siren's Song", description = "She's still out there... Ophelia, the Siren of the Highlands! Her terrible song will lure you to the depths. I've vowed to stay behind and avenge my fallen crewmates, {class}. If you want to join me, just say the word.\n\nWe'll lash ourselves to the mast, we will. We'll shut our eyes. We'll stuff our ears with wax. And when her beautiful illusion drops... we'll strike.\n\nAre you in?", completion = "She had me under her spell, {name}. I wouldn't have made it out of there alive if it weren't for you. Thank you!\n\nMaybe the rest of the Alliance fleet can finally anchor here in peace...", objectives = "Slay Ophelia, the Siren of the Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27201] = { id = 27201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'kyr Incursion", description = "The val'kyr were one of the Scourge's primary weapons.  Not only were they skilled in battle, but they could be used to convert corpses into Scourge minions.  To think that Sylvanas is stooping to such levels for the sake of the Forsaken...\n\nWe need to stop the val'kyr before they wipe us out and turn our army against us.  Slay as many as you can find.  And bring some of these minutemen with you.  If they've survived this long, then they must have some battle skill.", completion = "For every val'kyr you slay, you save dozens of our men... and prevent the Forsaken forces from growing.\n\nStill, they press on.  We may not win this battle after all.", objectives = "Kill 9 Lesser Val'kyr within Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27202] = { id = 27202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Against Brother", description = "Our militia has been nearly wiped out.  Only I and these few farmers remain.\n\nThose winged creatures... they took the bodies of our men and... and turned them into walking, undead corpses!  With every one of our men they took, they bolstered their own ranks.\n\nIt pains me to admit it, but you will need to fight them too, along with the deathguards and val'kyr.  As they did in life, they hunt in packs, so take some of my minutemen with you.", completion = "You fought valiantly, but we're getting nowhere.  Every body that falls just fuels their forces.", objectives = "Kill 20 Forsaken Troopers within Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27203] = { id = 27203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Maelstrom", description = "Thank the spirits you're here, {name}.\n\nWe're not sure how much longer we can maintain the rift in the Maelstrom.\n\nOur most powerful members, led by Thrall, are barely preventing the tear.\n\nLast I heard, our only hope was to go through the breach and attempt to stabilize it from the other side.\n\nI will conjure a portal.  Take it and report to Thrall as soon as you can.", completion = "<Thrall's muscles strain as primal energy flows through him.  His eyes shift your way, acknowledging your arrival.>\n\nIt is good to see you, {name}.", objectives = "Go through the Portal to the Maelstrom and speak to Thrall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27204] = { id = 27204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aradne", description = "Our last hope of victory lies in defeating the val'kyr.  You've done well up until now... but you're only one <man/woman> and there are literally dozens of them raining destruction on the battlefield.\n\nOne enormous val'kyr sits atop the tower to our south... you can see her from here.  Perhaps if we eliminate her, the remaining val'kyr will dissipate.\n\nThis is our only hope.  Bring some of Grant's men with you.  You'll need their protection for this battle.", completion = "I watched your victory from below.  Well-fought, but ultimately, it was for naught.\n\nThe val'kyr and the Forsaken press on; soon, they will overtake us.  We have lost Andorhal.", objectives = "Slay Aradne atop the tower in western Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27205] = { id = 27205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Depravity of the Forsaken", description = "We nearly have this battle won, {name}.  I can taste victory.  The Forsaken never stood a...\n\nWhat the hell is that!?", completion = "Val'kyr?  Koltira brought val'kyr to this fight?  Has he gone mad?\n\nNo, this is not Koltira's work.  This was Sylvanas.", objectives = "Find out what Thassarian is looking at.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27206] = { id = 27206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alas, Andorhal", description = "Head south, to Chillwind Camp.  Tell Commander Ashlam Valorfist everything that happened here.\n\nMe?  I'm going west, into Tirisfal.\n\nMy battle's not over yet.  I've got an appointment with that harpy that calls herself a Banshee Queen... and I'm finding out what she did to Koltira.", completion = "Lost?  No... next, they'll be coming for Chillwind, I suppose.  This was a major strategic blow to the Alliance's plans for Lordaeron.\n\nVery well.  I will report the results of this battle to King Wrynn.  I don't expect him to be happy.", objectives = "Report the events of the battle of Andorhal to Commander Ashlam Valorfist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27207] = { id = 27207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Blows", description = "Is THAT what's behind the storms assailing my city?\n\nLet's push on. That towering windbag can bellow and blow all he likes, but this is the end of him. Tell General Marcus Jonathan what's happened here when we've gotten back; I'll need to oversee the return of the citizenry, repairs, and so on.", completion = "A massive prince of the wind, you say? The herald of Al'Akir, the Windlord?\n\nMadness. All of it.\n\nStormwind is in your debt, hero.", objectives = "Slay Prince Sarsarun and inform General Marcus Jonathan in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27208] = { id = 27208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreadlord Balnazzar", description = "With the fall of the Scarlet Crusade, their disguised demon leader, Balnazzar, released the possessed body of Grand Crusader Dathrohan and went on a rampage, killing every remaining crusader here. He then used his necromantic power to raise them all as vile undead slaves.\n\nBalnazzar refers to his new army as the Risen. We cannot let him grow this army - they are extremely powerful and, unlike Arthas' Scourge, Balnazzar will not hold his forces back. Kill him while we still have a chance, {class}.", progress = "The Light commands you.", completion = "It's good we stopped Balnazzar now. Before long, his army would have overtaken all of Stratholme, giving him a powerful center for his new unholy empire.", objectives = "Kill Balnazzar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27209] = { id = 27209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Blows", description = "So. This is what evil lies behind the attacks on fair Thunder Bluff.\n\nLet us move forward. It is time to put an end to this abomination.\n\nTell Hamuul Runetotem what has happened here upon our return; I'll need to oversee the return of my people, repairs, and the like.", completion = "A massive prince of the wind, you say? The herald of Al'Akir, the Windlord?\n\nMadness. All of it.\n\nAll of Thunder Bluff is in your debt, {class}.", objectives = "Slay Prince Sarsarun and inform Hamuul Runetotem in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27210] = { id = 27210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitors Among Us", description = "It's good to meet you, {class}. I've come to Theramore to help eliminate the problem of the deserters. Not only have some of the men abandoned their posts, but some have filtered back into the town.\n\nThese deserter agents are spreading lies and propaganda, hoping to convince others to join their ranks.\n\nThey're at virtually every guard post throughout the town and the docks. Find them, expose them, and discredit them. At this point, anything more risks inspiring more sympathy for them.", completion = "Well done, {name}. I think we managed to catch them off guard. Their agents probably thought themselves safe within the city walls.\n\nGiven time, the agitators will return and spread their lies again. We'll use the time you've bought to shut out the deserters further.", objectives = "Confront 5 Deserter Agitators in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27211] = { id = 27211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Propaganda War", description = "The deserter agents were doing far more than just chatting up the guards. We've found a number of leaflets the deserters somehow managed to smuggle in on a ship in the docks.\n\nThe ship used to transport the leaflets is still in Theramore, at the farthest dock. If you can sneak aboard and capture the rest of their propaganda documents, their agents will lose their most powerful tool. Be careful! The ship is manned by seasoned privateers and the cargo is probably being kept in the captain's quarters.", progress = "Did you manage to find and capture the remaining propaganda leaflets?", completion = "<The SI:7 agent nods in approval.>\n\nExcellent. All that remains is to discredit the deserters so that they'll never gain a foothold in Theramore again, and I have just the plan to do it.", objectives = "Obtain the Deserter Propaganda from the boat at the end of the Theramore docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27212] = { id = 27212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discrediting the Deserters", description = "I've altered the leaflets you captured from the deserters' mercenary friends at the docks. Now, anyone who reads them will get an entirely different view of the deserters and their aims.\n\nIf we distribute these to enough of the guards, the deserters will be too embarrassed to ever reestablish their presence within our walls.\n\n<Calia hands you a stack of the altered leaflets.>\n\nWhy don't you get started while I plan our next move?", progress = "I thought I heard laughter coming from the barracks. Did you distribute those leaflets I gave you?", completion = "<Calia chuckles as you describe the guards' reactions to the propaganda.>\n\nJust as I'd hoped! I think it's safe to say any deserter agents who try to infiltrate Theramore will be laughed right out of town!", objectives = "Distribute the Altered Leaflets to 6 Theramore Guards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27213] = { id = 27213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End of the Deserters", description = "Now that we've eliminated the deserters from Theramore, it's time to complete this operation. My local contacts have reported that the deserters base their operations in a ship moored on a small island to the southeast of the docks.\n\nArresting their leader, Gavis Greyshield, should cause the others to lose their will to fight. Find him within the ship and convince him to surrender. I wouldn't be surprised if he puts up a bit of a fight for show, but then surrenders when he understands he can't win.", progress = "Have you completed your assault on the deserter base?", completion = "Gavis' request isn't as outlandish as it might sound. With the proper handling, Lady Jaina can return the deserters to the fold, but that is her decision, of course.\n\nIt's been a pleasure working with you, {name}. Without your help, I doubt the operation would've gone so smoothly. When I make my report in Stormwind, it will name you as the {class} who ended the deserter threat.", objectives = "Defeat Gavis Greyshield aboard the ship southeast of Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27214] = { id = 27214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Disturbing Development", description = "Reports from our scout patrols have recently taken a disturbing turn. They tell of men wearing red Defias bandanas walking the Dreadmurk Shore north of Theramore's walls.\n\nWreckage in the area suggests they may be survivors of a shipwreck, but our information is limited. Captain Wymor at Sentry Point, a guard tower to the north of the city, is looking for help in following up on the reports.", completion = "<The captain makes no effort to hide that he's assessing your abilities.>\n\nSo you've heard about the recent shipwreck off the coast? Good, I could use some help confirming my suspicions about the survivors. Welcome aboard, {name}.", objectives = "Report to Captain Wymor at Sentry Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27215] = { id = 27215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit of Swamplight Manor", description = "There's a fellow the locals know as \"Swamp Eye\" Jarl, who lives alone out in the swamp. Sometime ago he \"took over\" Swamplight Manor after the previous owners disappeared under mysterious circumstances.\n\nI like to send someone to check up on him every once in a while. He kind of reminds me of my grandfather, you know? Some say he's not quite right in the head.\n\nIf you're headed northwest on the road out of Theramore, you'll find Swamplight Manor in the Witch Hill area, before the road turns west.", completion = "Get off my lawn... unless, that is, you want to help old \"Swamp Eye\" with a little bit of cooking. Whad'ya say?", objectives = "Speak to \"Swamp Eye\" Jarl at Swamplight Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27216] = { id = 27216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Old Lighthouse", description = "The old lighthouse out to the east hasn't worked for some time, but Babs Fizzletorque has gotten it into her head to get it working again.\n\nI don't know how she plans to do it by herself, but she claims that it'll make the movement of ships and goods into the docks smoother, so I can't really object. Drawing duty on the docks is really nothing to complain about when you could be on the front lines, you know?", completion = "Good. I can use all the help you can offer. My first priority is to get that lamp re-lit.", objectives = "Speak to Babs Fizzletorque at the lighthouse on the island east of Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27217] = { id = 27217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thresher Oil", description = "The old log in the lighthouse indicates that the lamp was fueled with oil from the threshers that live along the coast here.\n\n<Babs wrinkles her nose at the mention of such outdated technology.>\n\nI suppose it's a practical, if inelegant solution. The log says that the oil taken from the youngest murk threshers works the best, and those live right underneath the docks of Theramore.\n\nIf you're up for it, would you help resupply the lighthouse with fuel?", progress = "Were you able to get any of that thresher oil?", completion = "Well, I have my doubts, but this is the only solution available right now. Once we have it up and running, I'm sure there will be time to look at other ways to fuel the lamp.", objectives = "Collect 4 containers of Thresher Oil from Murk Threshers beneath the Theramore docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27218] = { id = 27218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dastardly Denizens of the Deep", description = "You know, it's amazing what you can find in that old lighthouse. After I lit the lamp, I noticed this book in one of the old trunks up there.\n\n<Babs holds up the book and reads the title dramatically.>\n\n\"Dastardly Denizens of the Deep!\"\n\nWhy, I think I might swoon if I ever saw one of these! I'm sure it's good for a laugh or two, but I simply don't have time for reading right now.\n\nYou know who might enjoy it, though... that fishmonger on the docks, \"Dirty\" Michael Crowe. He collects old books.", progress = "What'll it be today? The snook is quite good.", completion = "Well, now, that was thoughtful o' Babs to send that over. I don't know if you've leafed through it or not, but there's a lot of truth to the tales in that book. Sailors didn't just make it all up, you know.", objectives = "Bring Dastardly Denizens of the Deep to \"Dirty\" Michael Crowe on the Theramore docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27219] = { id = 27219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is it Real?", description = "Oh, I'm sure you and Babs had a good laugh over the outlandish descriptions and sketches in the book, but have you stopped to consider there might be some truth to the legends?\n\nIf you listen closely enough, I bet you can still hear sailors talk about Tethyr, the sea creature the book says lives right here! Of course, if you wanted to know for sure, you could always ask old Nat Pagle.\n\nHe's got a small fishing camp on a little island in Tidefury Cove, which is southwest across Dustwallow Bay.", completion = "So you want to know about sea monsters? Hmm... well, I'll make you a deal, but it's going to involve a lot of alcohol and some embarrassment on your part.", objectives = "Talk to Nat Pagle at Nat's Landing in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
